INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C1','math',6,1,'u5',2,'비율그래프 알기 — 띠그래프와 원그래프는 전체를 100 %로 보고 각 부분의 비율을 띠의 길이·원의 넓이로 나타내며, 같은 %라도 전체가 다르면 실제 수가 다르다는 것을 알기',ARRAY['6수05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C2','math',6,1,'u5',2,'띠그래프와 원그래프 읽기 — 가장 큰·작은 항목, 한 항목의 백분율, 두 항목의 합, 몇 배인지, 모르는 칸(100 − 나머지), 눈금 한 칸의 크기를 읽고, 전체 수 × 백분율로 항목의 수를 구하기',ARRAY['6수05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C3','math',6,1,'u5',3,'띠그래프로 나타내기 — 각 항목의 백분율(항목의 수 ÷ 전체 × 100)을 구하고, 합이 100 %인지 확인한 뒤 백분율만큼 띠의 길이를 나누어 내용·백분율·제목을 쓰기',ARRAY['6수05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C4','math',6,1,'u5',4,'원그래프로 나타내기 — 눈금이 20칸(한 칸 5 %)인 원에 원의 중심에서 눈금까지 선을 그어 백분율만큼 나누고, 반올림해 합이 99 %나 101 %가 되면 가장 큰 항목을 고쳐 100 %로 맞추기',ARRAY['6수05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C5','math',6,1,'u5',5,'자료를 모아 나타내고 해석하기 — 모은 자료를 표로 정리해 백분율을 구하고 띠그래프·원그래프로 나타낸 뒤, 그래프를 보고 가장 많은 것·몇 배·두 항목의 합 같은 사실을 찾아 해석하기',ARRAY['6수05-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C6','math',6,1,'u5',6,'여러 가지 그래프 비교하기 — 수는 막대그래프, 시간에 따른 변화는 꺾은선그래프, 전체에 대한 비율은 띠·원그래프가 잘 보여 주므로 목적을 먼저 정해 고르고, 비율그래프만으로는 실제 수를 알 수 없음을 알기',ARRAY['6수05-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C7','math',6,1,'u5',7,'그래프로 문제 해결하기 — 문제 제기 → 자료 수집 → 자료 분석(표·그래프) → 결과 해석의 네 단계로 탐구 문제의 답을 찾고, 해석한 결과를 실천으로 잇기',ARRAY['6수05-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C8','math',6,1,'u5',8,'그래프를 검토하고 고치기 — 백분율의 합이 100 %인지, 길이·넓이가 백분율과 맞는지, 내용·백분율·제목이 있는지 확인해 잘못된 값을 찾아 바르게 고쳐 다시 나타내기',ARRAY['6수05-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X01','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C5','M6-1-u5-C6']::text[],'같은 %이면 실제 수도 같다고 본다(전체 30일의 30 %와 60일의 30 %를 같은 날수로)','전체가 다르면 수도 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X02','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C5','M6-1-u5-C6']::text[],'비율그래프만 보고 실제 수를 알 수 있다고 보거나, 비율이 늘었으니 수도 늘었다고 단정한다','수를 알려면 전체를 알아야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X03','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C8']::text[],'백분율의 합이 100 %가 아니어도 된다고 보거나, 모르는 칸을 구할 때 100에서 빼지 않는다','부분을 모두 더하면 100 %') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X04','math',6,'u5',ARRAY['M6-1-u5-C3','M6-1-u5-C5']::text[],'백분율을 구할 때 100을 곱하지 않거나 10을 곱하고, 전체 ÷ 항목의 수로 거꾸로 나눈다','항목의 수 ÷ 전체 × 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X05','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C4']::text[],'눈금 한 칸의 크기를 칸 수로 나누지 않고 1 %·10 %로 본다(20칸 원의 한 칸을 1 %로)','100 ÷ 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X06','math',6,'u5',ARRAY['M6-1-u5-C4']::text[],'원그래프의 경계선을 원의 중심이 아닌 곳(둘레·아무 곳)에서 긋는다','중심에서 눈금까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X07','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2']::text[],'칸의 길이·넓이 대신 놓인 차례·위치로 크기를 판단한다(맨 앞 칸이 가장 크다고)','길이·넓이가 곧 비율') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X08','math',6,'u5',ARRAY['M6-1-u5-C4','M6-1-u5-C5']::text[],'반올림해 합이 99 %·101 %가 되었을 때 그대로 두거나, 모든 항목·가장 작은 항목을 고친다','가장 큰 항목을 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X09','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C5']::text[],'몇 배인지 물었는데 백분율의 차를 구한다','「몇 배」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X10','math',6,'u5',ARRAY['M6-1-u5-C6']::text[],'목적에 맞지 않는 그래프를 고른다(시간에 따른 변화를 원그래프로, 전체에 대한 비율을 꺾은선그래프로)','변화는 꺾은선, 비율은 띠·원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X11','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C6']::text[],'막대그래프·그림그래프로도 전체에 대한 비율이 한눈에 보인다고 보거나, 띠·원그래프로 각 항목의 정확한 수를 비교하려 한다','수는 막대, 비율은 띠·원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X12','math',6,'u5',ARRAY['M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5']::text[],'그래프로 나타내는 차례를 바꾼다(백분율을 구하기 전에 띠를 나누거나 제목·색칠부터)','백분율 → 합 100 → 나누기 → 쓰기 → 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X13','math',6,'u5',ARRAY['M6-1-u5-C7']::text[],'통계적 문제 해결 단계를 바꾸거나 섞는다(문제를 정하기 전에 자료부터 모으기, 표로 정리하기를 결과 해석으로)','제기 → 수집 → 분석 → 해석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X14','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C5']::text[],'항목의 수를 그대로 %로 읽거나, 백분율을 그대로 사람 수로 답한다(전체 20명 중 6명을 6 %로)','전체가 100이 아니면 바꾸어야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X15','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5','M6-1-u5-C6','M6-1-u5-C7','M6-1-u5-C8']::text[],'백분율·곱셈·나눗셈 셈을 잘못 한다','거꾸로 셈으로 검산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X16','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5','M6-1-u5-C6','M6-1-u5-C7','M6-1-u5-C8']::text[],'묻는 말을 놓친다 — 가장 큰↔작은, 나머지, 알 수 있는↔알 수 없는, 옳은↔옳지 않은','물음에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#1','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'mc','auto','띠그래프에서 한 칸의 길이가 나타내는 것은 무엇인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X02','M6-1-u5-X16']::text[],true,'{"seq":1,"concept":"M6-1-u5-C1","difficulty":1,"kind":"mc","stem":"띠그래프에서 한 칸의 길이가 나타내는 것은 무엇인가요?","options":[{"t":"그 항목이 전체에서 차지하는 비율","correct":true},{"t":"그 항목의 실제 수","mis":"M6-1-u5-X14"},{"t":"조사한 전체 수","mis":"M6-1-u5-X02"},{"t":"조사한 항목의 개수","mis":"M6-1-u5-X16"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."],"variant_rule":{"alt":[{"stem":"원그래프에서 한 조각의 넓이가 나타내는 것은 무엇인가요?","options":[{"t":"그 항목이 전체에서 차지하는 비율","correct":true},{"t":"그 항목의 실제 수","mis":"M6-1-u5-X14"},{"t":"조사한 전체 수","mis":"M6-1-u5-X02"},{"t":"원을 그린 차례","mis":"M6-1-u5-X07"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."]},{"stem":"띠그래프에서 다른 칸보다 더 긴 칸은 무엇을 뜻하나요?","options":[{"t":"전체에서 차지하는 비율이 더 큰 항목","correct":true},{"t":"맨 앞에 놓인 항목","mis":"M6-1-u5-X07"},{"t":"조사를 먼저 한 항목","mis":"M6-1-u5-X16"},{"t":"실제 수가 언제나 100보다 큰 항목","mis":"M6-1-u5-X14"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#2','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'mc','auto','전체에 대한 부분의 비율을 한눈에 알아보기에 알맞은 그래프는 어느 것인가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C1","difficulty":1,"kind":"mc","stem":"전체에 대한 부분의 비율을 한눈에 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"띠그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"각 항목이 전체에서 차지하는 비율을 원 모양으로 나타낸 그래프는 어느 것인가요?","options":[{"t":"원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."]},{"stem":"좋아하는 과일별 사람 수를 막대그래프로 나타냈어요. 막대그래프에서 한눈에 잘 보이지 않는 것은 어느 것인가요?","options":[{"t":"각 과일이 전체에서 차지하는 비율","correct":true},{"t":"과일별 사람 수","mis":"M6-1-u5-X11"},{"t":"가장 많은 사람이 좋아하는 과일","mis":"M6-1-u5-X11"},{"t":"두 과일의 사람 수 차","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#3','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',1,'mc','auto','좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#4','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'ox','auto','띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"원그래프만 보고는 각 항목의 실제 수를 알 수 없어요.","answer":"O","reason_options":[{"t":"전체 수를 알아야 실제 수를 구할 수 있기 때문에","correct":true},{"t":"원그래프에는 수가 적혀 있지 않아 비율도 모르기 때문에","mis":"M6-1-u5-X02"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#5','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 사과는 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 사과는 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","사과는 30 %예요.","답은 30이에요."],"mis":"M6-1-u5-X16","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 나쁨은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["띠그래프의 칸마다 항목과 백분율이 적혀 있어요.","나쁨은 30 %예요.","답은 30이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 로봇은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","로봇은 30 %예요.","답은 30이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#6','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#7','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#8','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',2,'sa','auto','전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 30일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","30 × 30 % = 9예요.","나쁨은 9일이에요."]},{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#9','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',2,'ox','auto','두 반 모두 30 %가 축구를 좋아하면 축구를 좋아하는 학생 수도 같아요.',ARRAY['M6-1-u5-X01']::text[],true,'{"seq":9,"concept":"M6-1-u5-C1","difficulty":2,"kind":"ox","stem":"두 반 모두 30 %가 축구를 좋아하면 축구를 좋아하는 학생 수도 같아요.","answer":"X","reason_options":[{"t":"두 반의 전체 학생 수가 다르면 수도 다르기 때문에","correct":true},{"t":"같은 %이면 언제나 같은 수이기 때문에","mis":"M6-1-u5-X01"}],"mis":"M6-1-u5-X01","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"막대그래프에서도 전체에 대한 비율이 한눈에 잘 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 각 항목의 수를 보여 주는 그래프이기 때문에","correct":true},{"t":"막대가 길수록 비율도 바로 읽히기 때문에","mis":"M6-1-u5-X11"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"띠그래프에서 맨 앞에 놓인 칸이 언제나 가장 큰 항목이에요.","answer":"X","reason_options":[{"t":"크기는 놓인 차례가 아니라 칸의 길이로 알기 때문에","correct":true},{"t":"가장 중요한 항목을 맨 앞에 두기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#10','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":10,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#1','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈는데 좋음의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 30 + 10 = 75예요.","100 − 75 = 25예요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태","hide":[0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#2','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',2,'mc','auto','「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":2,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]},{"stem":"「이번 달 미세 먼지가 나쁨인 날이 40 %였다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"이번 달 날수가 30일인지 31일인지","correct":true},{"t":"나쁨인 날의 비율","mis":"M6-1-u5-X16"},{"t":"나쁨이 아닌 날의 비율","mis":"M6-1-u5-X16"},{"t":"나쁨인 날이 절반보다 적었다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「이번 달 날수가 30일인지 31일인지」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#3','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#4','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#5','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',3,'error','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C1","difficulty":3,"kind":"error","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"도윤 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","하린은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"예준 — 「가 도시의 나쁨인 날은 5일이야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「나 도시의 나쁨인 날은 10일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 20 × 25 % = 5(일)이에요.","나 도시는 40 × 25 % = 10(일)이에요.","수아는 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"유진 — 「가 도시의 나쁨인 날은 6일이야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 20 % = 6(일)이에요.","나 도시는 90 × 20 % = 18(일)이에요.","가온은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#6','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'mc','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#7','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'error','auto','미세 먼지 상태 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16']::text[],true,'{"seq":7,"concept":"M6-1-u5-C2","difficulty":3,"kind":"error","stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「좋음이 맨 앞에 있으니까 가장 커.」","correct":true,"mis_target":"M6-1-u5-X07"},{"t":"예준 — 「가장 큰 항목은 보통이야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「보통과 나쁨 합하면 65 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 보통 35 %이고 가장 작은 항목은 매우 나쁨 10 %예요.","35 % + 30 % = 65 %예요.","수아가 잘못 말했어요 — 크기는 칸의 길이로 견주어요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「가장 작은 항목은 복숭아야.」","correct":true,"mis_target":"M6-1-u5-X16"},{"t":"유진 — 「가장 큰 항목은 복숭아야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「복숭아와 사과 합하면 70 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 복숭아 40 %이고 가장 작은 항목은 배 10 %예요.","40 % + 30 % = 70 %예요.","가온이 잘못 말했어요 — 크기는 칸의 넓이로 견주어요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"좋아하는 계절 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「가장 작은 항목은 봄이야.」","correct":true,"mis_target":"M6-1-u5-X16"},{"t":"시우 — 「가장 큰 항목은 봄이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「봄과 가을 합하면 60 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 봄 32 %이고 가장 작은 항목은 겨울 16 %예요.","32 % + 28 % = 60 %예요.","여울이 잘못 말했어요 — 크기는 칸의 길이로 견주어요."],"asset":{"type":"pgr","kind":"band","items":[["봄",32],["가을",28],["여름",24],["겨울",16]],"title":"좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#8','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',4,'sa','auto','나쁨인 날은 18일이고, 이것은 전체의 30 %예요. 전체는 몇 일인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C1","difficulty":4,"kind":"sa","stem":"나쁨인 날은 18일이고, 이것은 전체의 30 %예요. 전체는 몇 일인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["전체 × 30 % = 18이에요.","1 %는 18 ÷ 30 = 0.6이고 전체 100 %는 그 100배예요.","0.6 × 100 = 60 — 전체는 60일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"축구를 좋아하는 학생은 9명이고, 이것은 전체의 45 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["전체 × 45 % = 9예요.","1 %는 9 ÷ 45 = 0.2이고 전체 100 %는 그 100배예요.","0.2 × 100 = 20 — 전체는 20명이에요."]},{"stem":"가상 현실을 고른 학생은 12명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["전체 × 40 % = 12예요.","1 %는 12 ÷ 40 = 0.3이고 전체 100 %는 그 100배예요.","0.3 × 100 = 30 — 전체는 30명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#9','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',4,'sa','auto','소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. 종묘는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":4,"kind":"sa","stem":"소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. 종묘는 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["종묘의 백분율은 100 − (30 + 25 + 20 + 10) = 15예요.","20 × 15 % = 3이에요.","종묘는 3명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도의 백분율은 100 − (40 + 30 + 10) = 20이에요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"기르고 싶은 동물 조사(전체 25명)를 띠그래프로 나타냈는데 물고기의 백분율이 지워졌어요. 물고기는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["물고기의 백분율은 100 − (40 + 28 + 12) = 20이에요.","25 × 20 % = 5예요.","물고기는 5명이에요."],"asset":{"type":"pgr","kind":"band","items":[["강아지",40],["고양이",28],["물고기",20],["기타",12]],"title":"기르고 싶은 동물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#10','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',4,'essay','teacher','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C1","difficulty":4,"kind":"essay","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 도시는 30 × 30 % = 9이므로 9일, 나 도시는 60 × 30 % = 18이므로 18일이다. 비율은 같아도 전체 날수가 다르므로 나쁨인 날수는 나 도시가 더 많다.","scoring_points":["9일과 18일을 구했는가","나 도시가 더 많다고 답했는가","전체가 다르면 같은 %라도 수가 다르다고 설명했는가"]},"explanation":["가 도시 9일, 나 도시 18일이에요.","나 도시가 더 많아요.","전체가 다르면 같은 %라도 수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#1','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'mc','auto','띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 가장 마지막에 할 일은 무엇인가요?","options":[{"t":"제목 쓰기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율의 합이 100 %인지 확인하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「제목 쓰기」는 ⑤ 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"띠그래프로 나타낼 때 각 항목의 백분율을 구한 바로 다음에 할 일은 무엇인가요?","options":[{"t":"백분율의 합이 100 %인지 확인하기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「백분율의 합이 100 %인지 확인하기」는 ② 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#2','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 첨성대는 5명, 전체는 20명이에요. 첨성대의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","5 ÷ 20 × 100 = 25예요.","첨성대는 25 %예요."]},{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#3','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'mc','auto','완성한 띠그래프에 빠뜨리면 안 되는 것은 어느 것인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"완성한 띠그래프에 빠뜨리면 안 되는 것은 어느 것인가요?","options":[{"t":"항목의 내용과 백분율, 제목","correct":true},{"t":"조사한 날짜와 요일","mis":"M6-1-u5-X12"},{"t":"그린 사람의 이름","mis":"M6-1-u5-X12"},{"t":"칠한 색의 이름","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「항목의 내용과 백분율, 제목」이에요."],"variant_rule":{"alt":[{"stem":"띠그래프에서 각 칸의 길이를 정하는 것은 무엇인가요?","options":[{"t":"그 항목의 백분율","correct":true},{"t":"그 항목을 조사한 차례","mis":"M6-1-u5-X07"},{"t":"그 항목 이름의 글자 수","mis":"M6-1-u5-X07"},{"t":"그 항목의 실제 수 그대로","mis":"M6-1-u5-X14"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「그 항목의 백분율」이에요."]},{"stem":"띠그래프의 백분율 합이 100 %인지 확인하는 까닭은 무엇인가요?","options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많아 보이게 하려고","mis":"M6-1-u5-X16"},{"t":"띠를 예쁘게 칠하려고","mis":"M6-1-u5-X12"},{"t":"제목을 정하려고","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「띠 전체가 전체(100 %)를 나타내기 때문에」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#4','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'ox','auto','띠그래프를 그릴 때는 각 항목의 백분율부터 구해요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":4,"concept":"M6-1-u5-C3","difficulty":1,"kind":"ox","stem":"띠그래프를 그릴 때는 각 항목의 백분율부터 구해요.","answer":"O","reason_options":[{"t":"백분율을 알아야 띠를 얼마만큼 나눌지 알기 때문에","correct":true},{"t":"제목을 먼저 써야 하기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"띠그래프 각 칸의 백분율을 모두 더하면 100 %가 되어야 해요.","answer":"O","reason_options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"칸의 개수가 언제나 100개이기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프에는 제목을 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"무엇을 조사한 그래프인지 알 수 있게 제목을 써야 하기 때문에","correct":true},{"t":"칸에 내용이 있으면 제목은 필요 없기 때문에","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#5','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#6','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'mc','auto','소개하고 싶은 문화유산 조사에서 수원 화성은 4명, 전체는 20명이에요. 수원 화성의 백분율로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X04','M6-1-u5-X16']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":2,"kind":"mc","stem":"소개하고 싶은 문화유산 조사에서 수원 화성은 4명, 전체는 20명이에요. 수원 화성의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"20 %","correct":true},{"t":"4 %","mis":"M6-1-u5-X14"},{"t":"2 %","mis":"M6-1-u5-X04"},{"t":"80 %","mis":"M6-1-u5-X16"}],"explanation":["전체 20명 가운데 4명이에요.","4 ÷ 20 × 100 = 20이에요.","그래서 20 %예요."],"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 피구는 6명, 전체는 20명이에요. 피구의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"30 %","correct":true},{"t":"6 %","mis":"M6-1-u5-X14"},{"t":"3 %","mis":"M6-1-u5-X04"},{"t":"70 %","mis":"M6-1-u5-X16"}],"explanation":["전체 20명 가운데 6명이에요.","6 ÷ 20 × 100 = 30이에요.","그래서 30 %예요."]},{"stem":"기르고 싶은 동물 조사에서 고양이는 7명, 전체는 25명이에요. 고양이의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"28 %","correct":true},{"t":"7 %","mis":"M6-1-u5-X14"},{"t":"72 %","mis":"M6-1-u5-X16"},{"t":"38 %","mis":"M6-1-u5-X15"}],"explanation":["전체 25명 가운데 7명이에요.","7 ÷ 25 × 100 = 28이에요.","그래서 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#7','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','소개하고 싶은 문화유산 조사(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 종묘의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 종묘의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘는 3명이에요.","3 ÷ 20 × 100 = 15예요.","?는 15예요."],"mis":"M6-1-u5-X04","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사(축구 9명, 피구 6명, 야구 3명, 배구 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 야구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["야구는 3명이에요.","3 ÷ 20 × 100 = 15예요.","?는 15예요."],"asset":{"type":"pgr","kind":"band","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동","hide":[2]}},{"stem":"기르고 싶은 동물 조사(강아지 10명, 고양이 7명, 물고기 5명, 기타 3명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 물고기의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["물고기는 5명이에요.","5 ÷ 25 × 100 = 20이에요.","?는 20이에요."],"asset":{"type":"pgr","kind":"band","items":[["강아지",40],["고양이",28],["물고기",20],["기타",12]],"title":"기르고 싶은 동물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#8','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','길이가 20 cm인 띠를 전체로 하여 띠그래프를 그려요. 30 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"길이가 20 cm인 띠를 전체로 하여 띠그래프를 그려요. 30 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["띠 전체 20 cm가 100 %예요.","20 × 30 % = 6이에요.","6 cm로 나누어요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"길이가 10 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["띠 전체 10 cm가 100 %예요.","10 × 40 % = 4예요.","4 cm로 나누어요."]},{"stem":"길이가 40 cm인 띠를 전체로 하여 띠그래프를 그려요. 25 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠 전체 40 cm가 100 %예요.","40 × 25 % = 10이에요.","10 cm로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#9','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'ox','auto','전체 20명 가운데 6명이면 백분율은 6 %예요.',ARRAY['M6-1-u5-X14']::text[],true,'{"seq":9,"concept":"M6-1-u5-C3","difficulty":2,"kind":"ox","stem":"전체 20명 가운데 6명이면 백분율은 6 %예요.","answer":"X","reason_options":[{"t":"6 ÷ 20 × 100 = 30이라 30 %이기 때문에","correct":true},{"t":"항목의 수가 곧 백분율이기 때문에","mis":"M6-1-u5-X14"}],"mis":"M6-1-u5-X14","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"길이 10 cm인 띠에서 30 %는 3 cm예요.","answer":"O","reason_options":[{"t":"10 × 30 % = 3이기 때문에","correct":true},{"t":"30을 10으로 나누기 때문에","mis":"M6-1-u5-X15"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프에서 백분율이 큰 항목일수록 칸이 짧아요.","answer":"X","reason_options":[{"t":"백분율이 클수록 칸이 길기 때문에","correct":true},{"t":"큰 항목은 뒤에 두기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#10','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',3,'error','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C3","difficulty":3,"kind":"error","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 피구는 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「피구는 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"예준 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","수아는 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「강아지는 10명이니까 10 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"유진 — 「10 ÷ 25 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","10 ÷ 25 × 100 = 40이에요.","가온은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#1','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',2,'mc','auto','띠그래프로 나타낼 때 띠를 백분율만큼 나눈 바로 다음에 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C3","difficulty":2,"kind":"mc","stem":"띠그래프로 나타낼 때 띠를 백분율만큼 나눈 바로 다음에 할 일은 무엇인가요?","options":[{"t":"나눈 칸에 내용과 백분율 쓰기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율의 합이 100 %인지 확인하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「나눈 칸에 내용과 백분율 쓰기」는 ④ 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 각 항목의 백분율을 구한 바로 다음에 할 일은 무엇인가요?","options":[{"t":"백분율의 합이 100 %인지 확인하기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「백분율의 합이 100 %인지 확인하기」는 ② 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#2','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 40 %, 25 %, 20 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","40 + 25 + 20 = 85예요.","100 − 85 = 15예요."]},{"stem":"띠그래프 네 항목의 백분율이 32 %, 28 %, 24 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","32 + 28 + 24 = 84예요.","100 − 84 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#3','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','좋아하는 계절 조사(봄 8명, 가을 7명, 여름 6명, 겨울 4명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 겨울의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"좋아하는 계절 조사(봄 8명, 가을 7명, 여름 6명, 겨울 4명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 겨울의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["겨울은 4명이에요.","4 ÷ 25 × 100 = 16이에요.","?는 16이에요."],"mis":"M6-1-u5-X04","asset":{"type":"pgr","kind":"band","items":[["봄",32],["가을",28],["여름",24],["겨울",16]],"title":"좋아하는 계절","hide":[3]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(합창 18명, 미술 14명, 과학 11명, 독서 7명, 전체 50명)를 띠그래프로 나타내고 있어요. ?에 알맞은 과학의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["과학은 11명이에요.","11 ÷ 50 × 100 = 22예요.","?는 22예요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[2]}},{"stem":"먹고 싶은 간식 조사(떡볶이 14명, 과일 12명, 빵 8명, 과자 6명, 전체 40명)를 띠그래프로 나타내고 있어요. ?에 알맞은 과자의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["과자는 6명이에요.","6 ÷ 40 × 100 = 15예요.","?는 15예요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#4','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','길이가 15 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"길이가 15 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["띠 전체 15 cm가 100 %예요.","15 × 40 % = 6이에요.","6 cm로 나누어요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"길이가 25 cm인 띠를 전체로 하여 띠그래프를 그려요. 36 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["띠 전체 25 cm가 100 %예요.","25 × 36 % = 9예요.","9 cm로 나누어요."]},{"stem":"길이가 30 cm인 띠를 전체로 하여 띠그래프를 그려요. 70 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["21"],"explanation":["띠 전체 30 cm가 100 %예요.","30 × 70 % = 21이에요.","21 cm로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#5','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'mc','auto','빌린 책의 종류 조사에서 역사는 40권, 전체는 200권이에요. 역사의 백분율로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X04','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C3","difficulty":3,"kind":"mc","stem":"빌린 책의 종류 조사에서 역사는 40권, 전체는 200권이에요. 역사의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"20 %","correct":true},{"t":"40 %","mis":"M6-1-u5-X14"},{"t":"2 %","mis":"M6-1-u5-X04"},{"t":"80 %","mis":"M6-1-u5-X16"}],"explanation":["전체 200권 가운데 40권이에요.","40 ÷ 200 × 100 = 20이에요.","그래서 20 %예요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사에서 미술은 14명, 전체는 50명이에요. 미술의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"28 %","correct":true},{"t":"14 %","mis":"M6-1-u5-X14"},{"t":"72 %","mis":"M6-1-u5-X16"},{"t":"38 %","mis":"M6-1-u5-X15"}],"explanation":["전체 50명 가운데 14명이에요.","14 ÷ 50 × 100 = 28이에요.","그래서 28 %예요."]},{"stem":"학교에 오는 방법 조사에서 버스는 12명, 전체는 50명이에요. 버스의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"24 %","correct":true},{"t":"12 %","mis":"M6-1-u5-X14"},{"t":"76 %","mis":"M6-1-u5-X16"},{"t":"34 %","mis":"M6-1-u5-X15"}],"explanation":["전체 50명 가운데 12명이에요.","12 ÷ 50 × 100 = 24예요.","그래서 24 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#6','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'ox','auto','띠그래프에는 제목을 쓰지 않아도 돼요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":3,"kind":"ox","stem":"띠그래프에는 제목을 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"무엇을 조사한 그래프인지 알 수 있게 제목을 써야 하기 때문에","correct":true},{"t":"칸에 내용이 있으면 제목은 필요 없기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"전체 20명 가운데 6명이면 백분율은 6 %예요.","answer":"X","reason_options":[{"t":"6 ÷ 20 × 100 = 30이라 30 %이기 때문에","correct":true},{"t":"항목의 수가 곧 백분율이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프 각 칸의 백분율을 모두 더하면 100 %가 되어야 해요.","answer":"O","reason_options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"칸의 개수가 언제나 100개이기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#7','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','김밥의 3대 영양소 조사를 띠그래프로 나타냈는데 단백질의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"김밥의 3대 영양소 조사를 띠그래프로 나타냈는데 단백질의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 68 + 16 = 84예요.","100 − 84 = 16이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["탄수화물",68],["단백질",16],["지방",16]],"title":"김밥의 3대 영양소","hide":[1]},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 띠그래프로 나타냈는데 선물의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 25 + 20 + 5 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임","hide":[3]}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 밭의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 20 + 15 = 75예요.","100 − 75 = 25예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#8','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'error','auto','빌린 책의 종류 조사에서 과학은 50권, 전체는 200권이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":8,"concept":"M6-1-u5-C3","difficulty":4,"kind":"error","stem":"빌린 책의 종류 조사에서 과학은 50권, 전체는 200권이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「과학은 50권이니까 50 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"예준 — 「50 ÷ 200 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","50 ÷ 200 × 100 = 25예요.","수아는 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사에서 합창은 18명, 전체는 50명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합창은 18명이니까 18 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"유진 — 「18 ÷ 50 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","18 ÷ 50 × 100 = 36이에요.","가온은 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"학교에 오는 방법 조사에서 자전거는 10명, 전체는 50명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「자전거는 10명이니까 10 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"시우 — 「10 ÷ 50 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","10 ÷ 50 × 100 = 20이에요.","여울은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#9','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 길이가 10 cm인 띠를 전체로 하여 띠그래프를 그리면 경복궁 칸은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C3","difficulty":4,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 길이가 10 cm인 띠를 전체로 하여 띠그래프를 그리면 경복궁 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["경복궁의 백분율은 6 ÷ 20 × 100 = 30이에요.","띠 10 cm가 100 %니 10 × 30 % = 3이에요.","경복궁 칸은 3 cm예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 길이가 20 cm인 띠를 전체로 하여 띠그래프를 그리면 축구 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["축구의 백분율은 9 ÷ 20 × 100 = 45예요.","띠 20 cm가 100 %니 20 × 45 % = 9예요.","축구 칸은 9 cm예요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 길이가 15 cm인 띠를 전체로 하여 띠그래프를 그리면 강아지 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["강아지의 백분율은 10 ÷ 25 × 100 = 40이에요.","띠 15 cm가 100 %니 15 × 40 % = 6이에요.","강아지 칸은 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#10','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'essay','teacher','외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C3","difficulty":4,"kind":"essay","stem":"외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 각 항목의 백분율을 구한다 — 경복궁 6 ÷ 20 × 100 = 30, 첨성대 25, 수원 화성 20, 종묘 15, 기타 10. ② 30 + 25 + 20 + 15 + 10 = 100이므로 합이 100 %인지 확인한다. ③ 백분율만큼 띠의 길이를 나눈다. ④ 나눈 칸에 내용과 백분율을 쓴다. ⑤ 제목을 쓴다.","scoring_points":["다섯 항목의 백분율을 바르게 구했는가","합이 100인지 확인했는가","띠 나누기 → 내용·백분율 → 제목 차례를 썼는가"]},"explanation":["백분율은 30, 25, 20, 15, 10 %예요.","30 + 25 + 20 + 15 + 10 = 100이에요.","띠 나누기 → 내용·백분율 → 제목 차례로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#1','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'mc','auto','원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?',ARRAY['M6-1-u5-X06']::text[],true,'{"seq":1,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"원그래프를 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"백분율 구하기 → 합 100 % 확인 → 중심에서 선 긋기 → 내용·백분율 쓰기 → 제목 쓰기","correct":true},{"t":"제목 쓰기 → 백분율 구하기 → 중심에서 선 긋기 → 내용·백분율 쓰기","mis":"M6-1-u5-X12"},{"t":"중심에서 선 긋기 → 백분율 구하기 → 합 100 % 확인 → 제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율 구하기 → 둘레에서 선 긋기 → 내용·백분율 쓰기 → 제목 쓰기","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#2','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C4","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#3','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'mc','auto','원그래프와 띠그래프의 같은 점으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X10','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프와 띠그래프의 같은 점으로 옳은 것은 어느 것인가요?","options":[{"t":"둘 다 백분율의 합이 100 %예요","correct":true},{"t":"둘 다 원 모양이에요","mis":"M6-1-u5-X07"},{"t":"둘 다 시간에 따른 변화를 보여 줘요","mis":"M6-1-u5-X10"},{"t":"둘 다 각 항목의 실제 수를 보여 줘요","mis":"M6-1-u5-X02"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「둘 다 백분율의 합이 100 %예요」예요."],"variant_rule":{"alt":[{"stem":"원그래프와 띠그래프의 다른 점으로 옳은 것은 어느 것인가요?","options":[{"t":"원그래프는 넓이로, 띠그래프는 길이로 비율을 나타내요","correct":true},{"t":"원그래프만 전체를 100 %로 봐요","mis":"M6-1-u5-X03"},{"t":"띠그래프만 비율을 나타내요","mis":"M6-1-u5-X11"},{"t":"원그래프는 실제 수를, 띠그래프는 비율을 나타내요","mis":"M6-1-u5-X02"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「원그래프는 넓이로, 띠그래프는 길이로 비율을 나타내요」예요."]},{"stem":"원그래프로 나타내기에 알맞은 자료는 어느 것인가요?","options":[{"t":"전체에서 각 항목이 차지하는 비율","correct":true},{"t":"하루 동안의 기온 변화","mis":"M6-1-u5-X10"},{"t":"달마다 저금한 금액의 변화","mis":"M6-1-u5-X10"},{"t":"학년별 학생 수의 크기","mis":"M6-1-u5-X11"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「전체에서 각 항목이 차지하는 비율」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#4','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":1,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"원그래프는 원의 둘레 아무 곳에서나 선을 그어 나눠도 돼요.","answer":"X","reason_options":[{"t":"원의 중심에서 선을 그어야 넓이가 비율을 나타내기 때문에","correct":true},{"t":"조각의 개수만 맞으면 되기 때문에","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"눈금 20칸인 원그래프에서 35 %는 7칸이에요.","answer":"O","reason_options":[{"t":"35 ÷ 5 = 7이기 때문에","correct":true},{"t":"35를 20칸으로 나누기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#5','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#6','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#7','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈어요. 건설은 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈어요. 건설은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","건설은 38 %예요.","답은 38이에요."],"mis":"M6-1-u5-X16","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개는 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","3개는 37 %예요.","답은 37이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"용돈 쓰임 조사를 원그래프로 나타냈어요. 저금은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","저금은 35 %예요.","답은 35예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#8','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈어요. 사업장과 건설을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈어요. 사업장과 건설을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["사업장은 49 %, 건설은 38 %예요.","49 % + 38 % = 87 %예요.","답은 87이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물"},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 원그래프로 나타냈어요. 간식과 학용품을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["간식은 25 %, 학용품은 20 %예요.","25 % + 20 % = 45 %예요.","답은 45예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}},{"stem":"마을 땅 쓰임 조사를 원그래프로 나타냈어요. 밭과 과수원을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["밭은 25 %, 과수원은 20 %예요.","25 % + 20 % = 45 %예요.","답은 45예요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#9','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'ox','auto','반올림한 백분율의 합이 101 %이면 가장 큰 항목을 1 % 줄여요.',ARRAY['M6-1-u5-X08']::text[],true,'{"seq":9,"concept":"M6-1-u5-C4","difficulty":2,"kind":"ox","stem":"반올림한 백분율의 합이 101 %이면 가장 큰 항목을 1 % 줄여요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 100보다 커도 그대로 그리면 되기 때문에","mis":"M6-1-u5-X08"}],"mis":"M6-1-u5-X08","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"반올림한 백분율의 합이 99 %이면 가장 작은 항목을 1 % 늘려요.","answer":"X","reason_options":[{"t":"가장 큰 항목을 늘려 100 %로 맞추기 때문에","correct":true},{"t":"작은 항목이 더 정확하지 않기 때문에","mis":"M6-1-u5-X08"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"원그래프에서 25 %는 원의 넓이의 4분의 1이에요.","answer":"O","reason_options":[{"t":"100 %의 4분의 1이 25 %이기 때문에","correct":true},{"t":"원을 4개 그려야 하기 때문에","mis":"M6-1-u5-X07"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#10','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#1','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 80 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","80 ÷ 5 = 16이에요.","16칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 25 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","25 ÷ 5 = 5예요.","5칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#2','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 원그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}},{"stem":"김밥의 3대 영양소 조사를 원그래프로 나타냈는데 지방의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 68 + 16 = 84예요.","100 − 84 = 16이에요."],"asset":{"type":"pgr","kind":"pie","items":[["탄수화물",68],["단백질",16],["지방",16]],"title":"김밥의 3대 영양소","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#3','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'sa','auto','전체 30명 가운데 버스를 타는 학생이 7명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"전체 30명 가운데 버스를 타는 학생이 7명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["7 ÷ 30 × 100을 계산하면 23.3…예요.","소수 첫째 자리에서 반올림해요.","그래서 23 %예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"전체 12명 가운데 안경을 쓴 학생이 5명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["5 ÷ 12 × 100을 계산하면 41.6…예요.","소수 첫째 자리에서 반올림해요.","그래서 42 %예요."]},{"stem":"전체 24명 가운데 피아노를 배우는 학생이 11명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["11 ÷ 24 × 100을 계산하면 45.8…예요.","소수 첫째 자리에서 반올림해요.","그래서 46 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#4','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 36 %, 35 %, 30 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["35"],"explanation":["36 + 35 + 30 = 101이에요.","가장 큰 항목 36을 1 줄여 고쳐요.","36 − 1 = 35예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 61 %, 22 %, 16 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["62"],"explanation":["61 + 22 + 16 = 99예요.","가장 큰 항목 61을 1 늘려 고쳐요.","61 + 1 = 62예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#5','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'error','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X08','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C4","difficulty":3,"kind":"error","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「가장 작은 21 %를 20 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"도윤 — 「더하면 101 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「가장 큰 47 %를 46 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목을 47에서 46으로 고쳐 100 %로 맞춰요.","하린은 가장 작은 항목을 고친다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「가장 작은 27 %를 28 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"예준 — 「더하면 99 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가장 큰 38 %를 39 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목을 38에서 39로 고쳐 100 %로 맞춰요.","수아는 가장 작은 항목을 고친다고 잘못 말했어요."]},{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「가장 작은 24 %를 25 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"유진 — 「더하면 99 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「가장 큰 44 %를 45 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목을 44에서 45로 고쳐 100 %로 맞춰요.","가온은 가장 작은 항목을 고친다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#6','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'mc','auto','탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":3,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"3개","correct":true},{"t":"1개 이하","mis":"M6-1-u5-X16"},{"t":"2개","mis":"M6-1-u5-X07"},{"t":"4개","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","3개가 37 %로 가장 커요.","그래서 답은 3개예요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"논","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"밭","mis":"M6-1-u5-X07"},{"t":"과수원","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","논이 40 %로 가장 커요.","그래서 답은 논이에요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}},{"stem":"용돈 쓰임 조사를 원그래프 로 나타냈어요. 비율이 가장 작은 항목은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"저금","mis":"M6-1-u5-X16"},{"t":"간식","mis":"M6-1-u5-X07"},{"t":"학용품","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","기타가 5 %로 가장 작아요.","그래서 답은 기타예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#7','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":7,"concept":"M6-1-u5-C4","difficulty":3,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"눈금 20칸인 원그래프에서 35 %는 7칸이에요.","answer":"O","reason_options":[{"t":"35 ÷ 5 = 7이기 때문에","correct":true},{"t":"35를 20칸으로 나누기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"원그래프에서 25 %는 원의 넓이의 4분의 1이에요.","answer":"O","reason_options":[{"t":"100 %의 4분의 1이 25 %이기 때문에","correct":true},{"t":"원을 4개 그려야 하기 때문에","mis":"M6-1-u5-X07"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#8','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'sa','auto','눈금이 20칸인 원그래프에 35 %인 항목과 25 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C4","difficulty":4,"kind":"sa","stem":"눈금이 20칸인 원그래프에 35 %인 항목과 25 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목을 합하면 35 % + 25 % = 60 %예요.","눈금 한 칸은 5 %예요.","60 ÷ 5 = 12 — 12칸이에요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에 40 %인 항목과 15 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["두 항목을 합하면 40 % + 15 % = 55 %예요.","눈금 한 칸은 5 %예요.","55 ÷ 5 = 11 — 11칸이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에 18 %인 항목과 22 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 항목을 합하면 18 % + 22 % = 40 %예요.","눈금 한 칸은 5 %예요.","40 ÷ 5 = 8 — 8칸이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#9','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'sa','auto','전체 60명 가운데 걸어서 오는 학생이 17명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C4","difficulty":4,"kind":"sa","stem":"전체 60명 가운데 걸어서 오는 학생이 17명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["17 ÷ 60 × 100을 계산하면 28.3…예요.","소수 첫째 자리에서 반올림해요.","그래서 28 %예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"전체 70명 가운데 줄넘기를 잘하는 학생이 19명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["19 ÷ 70 × 100을 계산하면 27.1…예요.","소수 첫째 자리에서 반올림해요.","그래서 27 %예요."]},{"stem":"전체 80명 가운데 아침밥을 먹고 온 학생이 23명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["23 ÷ 80 × 100을 계산하면 28.7…예요.","소수 첫째 자리에서 반올림해요.","그래서 29 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#10','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'essay','teacher','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 이대로 원그래프를 그려도 되는지 판단하고, 어떻게 고쳐 그리면 되는지 눈금 칸 수와 함께 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C4","difficulty":4,"kind":"essay","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 이대로 원그래프를 그려도 되는지 판단하고, 어떻게 고쳐 그리면 되는지 눈금 칸 수와 함께 설명해 보세요.","answer_guide":{"answer":"예: 47 + 33 + 21 = 101이라 100 %가 아니므로 그대로 그리면 안 된다. 가장 큰 항목 47 %를 1 % 줄여 46 %로 고치면 46 + 33 + 21 = 100이 된다. 눈금 한 칸이 5 %인 원에 원의 중심에서 선을 그어 백분율만큼 나누고, 내용·백분율·제목을 쓴다.","scoring_points":["합이 101이라 고쳐야 한다고 판단했는가","가장 큰 항목을 46 %로 고쳤는가","원의 중심에서 선을 그어 나눈다고 썼는가"]},"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목을 46 %로 고쳐요.","중심에서 선을 그어 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#1','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'mc','auto','모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12','M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."],"variant_rule":{"alt":[{"stem":"그래프를 「해석한다」는 것은 무엇을 하는 것인가요?","options":[{"t":"그래프를 보고 알 수 있는 사실을 찾는 것","correct":true},{"t":"그래프를 예쁘게 색칠하는 것","mis":"M6-1-u5-X16"},{"t":"그래프를 다시 그리는 것","mis":"M6-1-u5-X12"},{"t":"그래프의 제목을 바꾸는 것","mis":"M6-1-u5-X16"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「그래프를 보고 알 수 있는 사실을 찾는 것」이에요."]},{"stem":"자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 모으기 → 표 → 백분율 → 그래프 → 해석","correct":true},{"t":"그래프 → 표 → 자료 모으기 → 해석","mis":"M6-1-u5-X12"},{"t":"자료 모으기 → 그래프 → 백분율 → 표","mis":"M6-1-u5-X12"},{"t":"백분율 → 자료 모으기 → 해석 → 표","mis":"M6-1-u5-X12"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「자료 모으기 → 표 → 백분율 → 그래프 → 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#2','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'sa','auto','해 보고 싶은 체험 활동 조사에서 가상 현실은 16명, 전체는 40명이에요. 가상 현실의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C5","difficulty":1,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사에서 가상 현실은 16명, 전체는 40명이에요. 가상 현실의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","16 ÷ 40 × 100 = 40이에요.","가상 현실은 40 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사에서 요리는 8명, 전체는 40명이에요. 요리의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","8 ÷ 40 × 100 = 20이에요.","요리는 20 %예요."]},{"stem":"들고 싶은 동아리 조사에서 합창은 18명, 전체는 50명이에요. 합창의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","18 ÷ 50 × 100 = 36이에요.","합창은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#3','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'mc','auto','해 보고 싶은 체험 활동 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"합창","correct":true},{"t":"독서","mis":"M6-1-u5-X16"},{"t":"미술","mis":"M6-1-u5-X07"},{"t":"과학","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","합창이 36 %로 가장 커요.","그래서 답은 합창이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}},{"stem":"먹고 싶은 간식 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"떡볶이","correct":true},{"t":"과자","mis":"M6-1-u5-X16"},{"t":"과일","mis":"M6-1-u5-X07"},{"t":"빵","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","떡볶이가 35 %로 가장 커요.","그래서 답은 떡볶이예요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#4','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'ox','auto','자료를 모으면 표로 정리하고 백분율을 구한 뒤 그래프로 나타내요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":4,"concept":"M6-1-u5-C5","difficulty":1,"kind":"ox","stem":"자료를 모으면 표로 정리하고 백분율을 구한 뒤 그래프로 나타내요.","answer":"O","reason_options":[{"t":"백분율을 알아야 비율그래프를 그릴 수 있기 때문에","correct":true},{"t":"그래프를 먼저 그리고 표를 만들기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"그래프를 그린 뒤에는 그래프를 보고 알 수 있는 사실을 찾아요.","answer":"O","reason_options":[{"t":"그래프는 해석해야 쓸모가 있기 때문에","correct":true},{"t":"그래프를 그리면 할 일이 끝나기 때문에","mis":"M6-1-u5-X13"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"같은 자료를 띠그래프와 원그래프로 나타내면 두 그래프의 백분율은 서로 달라요.","answer":"X","reason_options":[{"t":"같은 자료이면 백분율이 같고 모양만 다르기 때문에","correct":true},{"t":"원은 넓이를 써서 백분율이 커지기 때문에","mis":"M6-1-u5-X07"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#5','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'match','auto','해 보고 싶은 체험 활동 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명)','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C5","difficulty":2,"kind":"match","stem":"해 보고 싶은 체험 활동 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명)","pairs":[{"l":"가상 현실","r":"40 %"},{"l":"로봇","r":"30 %"},{"l":"요리","r":"20 %"},{"l":"목공","r":"10 %"}],"mis":"M6-1-u5-X04","explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","16 ÷ 40 × 100 = 40, 12 ÷ 40 × 100 = 30이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)에서 항목과 백분율을 알맞게 이으세요. (합창 18명, 미술 14명, 과학 11명, 독서 7명)","pairs":[{"l":"합창","r":"36 %"},{"l":"미술","r":"28 %"},{"l":"과학","r":"22 %"},{"l":"독서","r":"14 %"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","18 ÷ 50 × 100 = 36, 14 ÷ 50 × 100 = 28이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."]},{"stem":"먹고 싶은 간식 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (떡볶이 14명, 과일 12명, 빵 8명, 과자 6명)","pairs":[{"l":"떡볶이","r":"35 %"},{"l":"과일","r":"30 %"},{"l":"빵","r":"20 %"},{"l":"과자","r":"15 %"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","14 ÷ 40 × 100 = 35, 12 ÷ 40 × 100 = 30이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#6','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 과일의 비율은 과자의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["과일은 30 %, 과자는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"좋아하는 운동 조사를 띠그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"band","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#7','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 빵은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["빵은 20 %예요.","40 × 20 % = 8이에요.","빵은 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 피구는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["피구는 30 %예요.","20 × 30 % = 6이에요.","피구는 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#8','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 빵과 과자를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["빵은 20 %, 과자는 15 %예요.","20 % + 15 % = 35 %예요.","답은 35예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"들고 싶은 동아리 조사를 띠그래프로 나타냈어요. 미술과 과학을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["미술은 28 %, 과학은 22 %예요.","28 % + 22 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#9','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'ox','auto','가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.',ARRAY['M6-1-u5-X09']::text[],true,'{"seq":9,"concept":"M6-1-u5-C5","difficulty":2,"kind":"ox","stem":"가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.","answer":"X","reason_options":[{"t":"40 ÷ 10 = 4라 4배이기 때문에","correct":true},{"t":"40 − 10 = 30이기 때문에","mis":"M6-1-u5-X09"}],"mis":"M6-1-u5-X09","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"전체 40명 가운데 요리가 20 %이면 요리를 고른 학생은 8명이에요.","answer":"O","reason_options":[{"t":"40 × 20 % = 8이기 때문에","correct":true},{"t":"40 − 20 = 20이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"반올림해 합이 99 %가 되면 가장 큰 항목을 1 % 늘려 그려요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 99 %여도 그대로 그리기 때문에","mis":"M6-1-u5-X08"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#10','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',3,'error','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"하린 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"도윤 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","하린은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사(전체 20명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「경복궁은 기타보다 20배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「경복궁이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「경복궁은 6명이야.」","mis":"M6-1-u5-X16"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이니 3배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사(전체 50명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"가온 — 「복숭아는 배보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"유진 — 「복숭아가 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「복숭아는 20명이야.」","mis":"M6-1-u5-X16"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4니 4배예요.","가온은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#1','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',2,'mc','auto','자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C5","difficulty":2,"kind":"mc","stem":"자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 모으기 → 표 → 백분율 → 그래프 → 해석","correct":true},{"t":"그래프 → 표 → 자료 모으기 → 해석","mis":"M6-1-u5-X12"},{"t":"자료 모으기 → 그래프 → 백분율 → 표","mis":"M6-1-u5-X12"},{"t":"백분율 → 자료 모으기 → 해석 → 표","mis":"M6-1-u5-X12"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「자료 모으기 → 표 → 백분율 → 그래프 → 해석」이에요."],"variant_rule":{"alt":[{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]},{"stem":"그래프를 「해석한다」는 것은 무엇을 하는 것인가요?","options":[{"t":"그래프를 보고 알 수 있는 사실을 찾는 것","correct":true},{"t":"그래프를 예쁘게 색칠하는 것","mis":"M6-1-u5-X16"},{"t":"그래프를 다시 그리는 것","mis":"M6-1-u5-X12"},{"t":"그래프의 제목을 바꾸는 것","mis":"M6-1-u5-X16"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「그래프를 보고 알 수 있는 사실을 찾는 것」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#2','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈는데 요리의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈는데 요리의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동","hide":[2]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사를 띠그래프로 나타냈는데 과학의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 36 + 28 + 14 = 78이에요.","100 − 78 = 22예요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[2]}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈는데 빵의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 30 + 15 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#3','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'mc','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C5","difficulty":3,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#4','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'sa','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈는데 목공의 백분율이 지워졌어요. 목공은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C5","difficulty":3,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈는데 목공의 백분율이 지워졌어요. 목공은 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["목공의 백분율은 100 − (40 + 30 + 20) = 10이에요.","40 × 10 % = 4예요.","목공은 4명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동","hide":[3]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈는데 독서의 백분율이 지워졌어요. 독서는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["독서의 백분율은 100 − (36 + 28 + 22) = 14예요.","50 × 14 % = 7이에요.","독서는 7명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[3]}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 띠그래프로 나타냈는데 과자의 백분율이 지워졌어요. 과자는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["과자의 백분율은 100 − (35 + 30 + 20) = 15예요.","40 × 15 % = 6이에요.","과자는 6명이에요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#5','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'error','auto','좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「복숭아는 배보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「복숭아가 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「복숭아는 20명이야.」","mis":"M6-1-u5-X16"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"가온 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"유진 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","가온은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"여울 — 「경복궁은 기타보다 20배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"시우 — 「경복궁이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「경복궁은 6명이야.」","mis":"M6-1-u5-X16"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이니 3배예요.","여울은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#6','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'sa','auto','반올림해 구한 세 항목의 백분율이 41 %, 35 %, 25 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 41 %, 35 %, 25 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["41 + 35 + 25 = 101이에요.","가장 큰 항목 41을 1 줄여 고쳐요.","41 − 1 = 40이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 46 %, 29 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["47"],"explanation":["46 + 29 + 24 = 99예요.","가장 큰 항목 46을 1 늘려 고쳐요.","46 + 1 = 47이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 39 %, 32 %, 30 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["38"],"explanation":["39 + 32 + 30 = 101이에요.","가장 큰 항목 39를 1 줄여 고쳐요.","39 − 1 = 38이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#7','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'ox','auto','가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.',ARRAY['M6-1-u5-X09']::text[],true,'{"seq":7,"concept":"M6-1-u5-C5","difficulty":3,"kind":"ox","stem":"가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.","answer":"X","reason_options":[{"t":"40 ÷ 10 = 4라 4배이기 때문에","correct":true},{"t":"40 − 10 = 30이기 때문에","mis":"M6-1-u5-X09"}],"mis":"M6-1-u5-X09","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"전체 40명 가운데 요리가 20 %이면 요리를 고른 학생은 8명이에요.","answer":"O","reason_options":[{"t":"40 × 20 % = 8이기 때문에","correct":true},{"t":"40 − 20 = 20이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"반올림해 합이 99 %가 되면 가장 큰 항목을 1 % 늘려 그려요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 99 %여도 그대로 그리기 때문에","mis":"M6-1-u5-X08"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#8','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'sa','auto','가상 현실을 고른 학생은 16명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C5","difficulty":4,"kind":"sa","stem":"가상 현실을 고른 학생은 16명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 40 % = 16이에요.","1 %는 16 ÷ 40 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"축구를 고른 학생은 9명이고, 이것은 전체의 45 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["전체 × 45 % = 9예요.","1 %는 9 ÷ 45 = 0.2이고 전체 100 %는 그 100배예요.","0.2 × 100 = 20 — 전체는 20명이에요."]},{"stem":"독서 동아리를 고른 학생은 7명이고, 이것은 전체의 14 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["전체 × 14 % = 7이에요.","1 %는 7 ÷ 14 = 0.5이고 전체 100 %는 그 100배예요.","0.5 × 100 = 50 — 전체는 50명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#9','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'sa','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 가상 현실은 목공보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C5","difficulty":4,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 가상 현실은 목공보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목의 백분율 차는 40 % − 10 % = 30 %예요.","40 × 30 % = 12예요.","가상 현실이 12명 더 많아요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈어요. 합창은 독서보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["11"],"explanation":["두 항목의 백분율 차는 36 % − 14 % = 22 %예요.","50 × 22 % = 11이에요.","합창이 11명 더 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 띠그래프로 나타냈어요. 떡볶이는 과자보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 항목의 백분율 차는 35 % − 15 % = 20 %예요.","40 × 20 % = 8이에요.","떡볶이가 8명 더 많아요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#10','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'essay','teacher','우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C5","difficulty":4,"kind":"essay","stem":"우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.","answer_guide":{"answer":"예: 가상 현실 16 ÷ 40 × 100 = 40, 로봇 30, 요리 20, 목공 10이고 합은 100 %이다. 이 백분율만큼 띠그래프(또는 원그래프)로 나타낸다. 그래프를 보면 가상 현실이 40 %로 가장 많고 목공의 4배이다.","scoring_points":["네 항목의 백분율을 구했는가","합 100을 확인하고 그래프로 나타낸다고 썼는가","그래프에서 바른 사실을 찾았는가"]},"explanation":["백분율은 40, 30, 20, 10 %예요.","합이 100 %인지 확인하고 그래프로 나타내요.","가상 현실이 가장 많고 목공의 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#1','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":1,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#2','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"우리 반 학생들이 좋아하는 운동이 전체에서 차지하는 비율을 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]},{"stem":"마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"그림그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「그림그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#3','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":3,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."],"variant_rule":{"alt":[{"stem":"그래프를 고를 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"무엇을 보여 주고 싶은지(목적)","correct":true},{"t":"무슨 색을 칠할지","mis":"M6-1-u5-X16"},{"t":"그래프 이름의 글자 수","mis":"M6-1-u5-X16"},{"t":"그래프를 그린 사람","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「무엇을 보여 주고 싶은지(목적)」예요."]},{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#4','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'ox','auto','시간에 따른 변화를 보려면 꺾은선그래프가 알맞아요.',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":4,"concept":"M6-1-u5-C6","difficulty":1,"kind":"ox","stem":"시간에 따른 변화를 보려면 꺾은선그래프가 알맞아요.","answer":"O","reason_options":[{"t":"꺾은선그래프는 선의 기울기로 변화를 보여 주기 때문에","correct":true},{"t":"꺾은선그래프는 비율을 보여 주기 때문에","mis":"M6-1-u5-X10"}],"mis":"M6-1-u5-X10","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"같은 자료라도 보여 주고 싶은 것에 따라 알맞은 그래프가 달라요.","answer":"O","reason_options":[{"t":"그래프마다 잘 보여 주는 것이 다르기 때문에","correct":true},{"t":"그래프는 아무것이나 써도 같기 때문에","mis":"M6-1-u5-X10"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"그래프를 고를 때는 목적을 먼저 정해요.","answer":"O","reason_options":[{"t":"무엇을 보여 줄지에 따라 그래프가 정해지기 때문에","correct":true},{"t":"그래프 모양이 예쁜 것을 먼저 고르기 때문에","mis":"M6-1-u5-X10"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#5','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'match','auto','보여 주고 싶은 것과 알맞은 그래프를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C6","difficulty":2,"kind":"match","stem":"보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"전체에 대한 부분의 비율","r":"띠그래프"},{"l":"시간에 따른 변화","r":"꺾은선그래프"},{"l":"항목별 수의 크기","r":"막대그래프"}],"mis":"M6-1-u5-X10","explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"전체에 대한 부분의 비율","r":"원그래프"},{"l":"달마다 달라지는 키","r":"꺾은선그래프"},{"l":"반별 학생 수 비교","r":"막대그래프"}],"explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."]},{"stem":"이번에는 다른 보기예요. 보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"용돈 쓰임의 비율","r":"원그래프"},{"l":"하루 동안의 기온 변화","r":"꺾은선그래프"},{"l":"마을별 생산량을 그림으로","r":"그림그래프"}],"explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#6','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'mc','auto','가 반은 20명, 나 반은 40명이에요. 두 반 모두 독서를 좋아하는 학생의 비율이 50 %예요. 독서를 좋아하는 학생 수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"가 반은 20명, 나 반은 40명이에요. 두 반 모두 독서를 좋아하는 학생의 비율이 50 %예요. 독서를 좋아하는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 50 %라도 전체가 다르면 수가 달라요.","가 반은 20 × 50 % = 10, 나 반은 40 × 50 % = 20이에요.","그래서 나 반이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 반은 25명, 나 반은 50명이에요. 두 반 모두 강아지를 키우는 학생의 비율이 40 %예요. 강아지를 키우는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가 반은 25 × 40 % = 10, 나 반은 50 × 40 % = 20이에요.","그래서 나 반이 더 많아요."]},{"stem":"가 반은 30명, 나 반은 60명이에요. 두 반 모두 피아노를 배우는 학생의 비율이 20 %예요. 피아노를 배우는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가 반은 30 × 20 % = 6, 나 반은 60 × 20 % = 12예요.","그래서 나 반이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#7','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'sa','auto','전체 40명 가운데 독서를 좋아하는 학생이 50 %예요. 독서를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C6","difficulty":2,"kind":"sa","stem":"전체 40명 가운데 독서를 좋아하는 학생이 50 %예요. 독서를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 50 % = 20이에요.","독서를 좋아하는 학생은 20명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 25명 가운데 강아지를 키우는 학생이 40 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","25 × 40 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]},{"stem":"전체 60명 가운데 자전거를 타는 학생이 35 %예요. 자전거를 타는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 35 % = 21이에요.","자전거를 타는 학생은 21명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#8','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'mc','auto','작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M6-1-u5-X02','M6-1-u5-X14']::text[],true,'{"seq":8,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"걸어서 오는 학생의 비율이 늘었어요","correct":true},{"t":"걸어서 오는 학생 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"걸어서 오는 학생이 5명 늘었어요","mis":"M6-1-u5-X14"},{"t":"전체 학생 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."],"variant_rule":{"alt":[{"stem":"작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"용돈에서 저금이 차지하는 비율이 줄었어요","correct":true},{"t":"저금한 금액이 줄었어요","mis":"M6-1-u5-X02"},{"t":"저금한 금액이 5원 줄었어요","mis":"M6-1-u5-X14"},{"t":"용돈이 줄었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]},{"stem":"작년에는 도서관에서 빌린 책 가운데 과학책이 20 %, 올해는 28 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"빌린 책에서 과학책이 차지하는 비율이 늘었어요","correct":true},{"t":"빌린 과학책 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"과학책을 8권 더 빌렸어요","mis":"M6-1-u5-X14"},{"t":"빌린 책 전체 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#9','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'ox','auto','원그래프로 각 항목의 정확한 수를 비교할 수 있어요.',ARRAY['M6-1-u5-X11']::text[],true,'{"seq":9,"concept":"M6-1-u5-C6","difficulty":2,"kind":"ox","stem":"원그래프로 각 항목의 정확한 수를 비교할 수 있어요.","answer":"X","reason_options":[{"t":"원그래프는 비율만 보여 주고 수는 전체를 알아야 하기 때문에","correct":true},{"t":"조각이 클수록 수가 정확히 보이기 때문에","mis":"M6-1-u5-X11"}],"mis":"M6-1-u5-X11","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"막대그래프로도 전체에 대한 비율이 한눈에 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 수의 크기를 보여 주기 때문에","correct":true},{"t":"막대 끝이 모두 100에 닿기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.","answer":"X","reason_options":[{"t":"전체 수가 줄었다면 수는 줄었을 수도 있기 때문에","correct":true},{"t":"비율이 늘면 수는 언제나 늘기 때문에","mis":"M6-1-u5-X02"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#10','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',3,'error','auto','「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C6","difficulty":3,"kind":"error","stem":"「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「원그래프로 그리면 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"도윤 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","하린은 목적에 맞지 않는 그래프를 골랐어요."],"variant_rule":{"alt":[{"stem":"「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「띠그래프로 그리면 온도 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"예준 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","수아는 목적에 맞지 않는 그래프를 골랐어요."]},{"stem":"「우리 반 학생들이 좋아하는 운동의 비율」을 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꺾은선그래프로 그리면 비율이 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"유진 — 「원그래프나 띠그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 전체에 대한 비율이에요.","전체에 대한 비율은 띠그래프·원그래프가 가장 잘 보여 줘요.","가온은 목적에 맞지 않는 그래프를 골랐어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#1','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',2,'mc','auto','마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":1,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"그림그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「그림그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#2','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',2,'mc','auto','가 반은 30명, 나 반은 60명이에요. 두 반 모두 안경을 쓴 학생의 비율이 30 %예요. 안경을 쓴 학생 수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"가 반은 30명, 나 반은 60명이에요. 두 반 모두 안경을 쓴 학생의 비율이 30 %예요. 안경을 쓴 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가 반은 30 × 30 % = 9, 나 반은 60 × 30 % = 18이에요.","그래서 나 반이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 반은 40명, 나 반은 80명이에요. 두 반 모두 걸어서 오는 학생의 비율이 25 %예요. 걸어서 오는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가 반은 40 × 25 % = 10, 나 반은 80 × 25 % = 20이에요.","그래서 나 반이 더 많아요."]},{"stem":"가 반은 20명, 나 반은 50명이에요. 두 반 모두 줄넘기를 하는 학생의 비율이 40 %예요. 줄넘기를 하는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가 반은 20 × 40 % = 8, 나 반은 50 × 40 % = 20이에요.","그래서 나 반이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#3','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]},{"stem":"가 학교 학생 300명 가운데 40 %, 나 학교 학생 500명 가운데 30 %가 걸어서 와요. 걸어서 오는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 300 × 40 % = 120(명)이에요.","나 학교는 500 × 30 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#4','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M6-1-u5-X02','M6-1-u5-X14']::text[],true,'{"seq":4,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"용돈에서 저금이 차지하는 비율이 줄었어요","correct":true},{"t":"저금한 금액이 줄었어요","mis":"M6-1-u5-X02"},{"t":"저금한 금액이 5원 줄었어요","mis":"M6-1-u5-X14"},{"t":"용돈이 줄었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."],"variant_rule":{"alt":[{"stem":"작년에는 도서관에서 빌린 책 가운데 과학책이 20 %, 올해는 28 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"빌린 책에서 과학책이 차지하는 비율이 늘었어요","correct":true},{"t":"빌린 과학책 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"과학책을 8권 더 빌렸어요","mis":"M6-1-u5-X14"},{"t":"빌린 책 전체 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]},{"stem":"작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"걸어서 오는 학생의 비율이 늘었어요","correct":true},{"t":"걸어서 오는 학생 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"걸어서 오는 학생이 5명 늘었어요","mis":"M6-1-u5-X14"},{"t":"전체 학생 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#5','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'error','auto','「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C6","difficulty":3,"kind":"error","stem":"「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「띠그래프로 그리면 온도 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"예준 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","수아는 목적에 맞지 않는 그래프를 골랐어요."],"variant_rule":{"alt":[{"stem":"「우리 반 학생들이 좋아하는 운동의 비율」을 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꺾은선그래프로 그리면 비율이 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"유진 — 「원그래프나 띠그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 전체에 대한 비율이에요.","전체에 대한 비율은 띠그래프·원그래프가 가장 잘 보여 줘요.","가온은 목적에 맞지 않는 그래프를 골랐어요."]},{"stem":"「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원그래프로 그리면 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"시우 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","여울은 목적에 맞지 않는 그래프를 골랐어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#6','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'ox','auto','작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.',ARRAY['M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C6","difficulty":3,"kind":"ox","stem":"작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.","answer":"X","reason_options":[{"t":"전체 수가 줄었다면 수는 줄었을 수도 있기 때문에","correct":true},{"t":"비율이 늘면 수는 언제나 늘기 때문에","mis":"M6-1-u5-X02"}],"mis":"M6-1-u5-X02","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"원그래프로 각 항목의 정확한 수를 비교할 수 있어요.","answer":"X","reason_options":[{"t":"원그래프는 비율만 보여 주고 수는 전체를 알아야 하기 때문에","correct":true},{"t":"조각이 클수록 수가 정확히 보이기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"막대그래프로도 전체에 대한 비율이 한눈에 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 수의 크기를 보여 주기 때문에","correct":true},{"t":"막대 끝이 모두 100에 닿기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#7','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":7,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."],"variant_rule":{"alt":[{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]},{"stem":"그래프를 고를 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"무엇을 보여 주고 싶은지(목적)","correct":true},{"t":"무슨 색을 칠할지","mis":"M6-1-u5-X16"},{"t":"그래프 이름의 글자 수","mis":"M6-1-u5-X16"},{"t":"그래프를 그린 사람","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「무엇을 보여 주고 싶은지(목적)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#8','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'mc','auto','가 학교 학생 250명 가운데 20 %, 나 학교 학생 400명 가운데 15 %가 안경을 써요. 안경을 쓰는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":8,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 250명 가운데 20 %, 나 학교 학생 400명 가운데 15 %가 안경을 써요. 안경을 쓰는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 250 × 20 % = 50(명)이에요.","나 학교는 400 × 15 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#9','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'sa','auto','독서를 좋아하는 학생은 12명이고, 이것은 전체의 30 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C6","difficulty":4,"kind":"sa","stem":"독서를 좋아하는 학생은 12명이고, 이것은 전체의 30 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 30 % = 12예요.","1 %는 12 ÷ 30 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"강아지를 키우는 학생은 9명이고, 이것은 전체의 25 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["전체 × 25 % = 9예요.","1 %는 9 ÷ 25 = 0.36이고 전체 100 %는 그 100배예요.","0.36 × 100 = 36 — 전체는 36명이에요."]},{"stem":"자전거를 타는 학생은 14명이고, 이것은 전체의 35 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 35 % = 14예요.","1 %는 14 ÷ 35 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#10','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'essay','teacher','「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 6개월 동안 읽은 책의 수 변화는 시간에 따른 변화이므로 꺾은선그래프가 알맞다. 이번 달 책의 종류별 비율은 전체에 대한 부분의 비율이므로 띠그래프나 원그래프가 알맞다. 보여 주고 싶은 것(목적)에 따라 그래프를 고른다.","scoring_points":["변화 → 꺾은선그래프를 골랐는가","비율 → 띠그래프·원그래프를 골랐는가","목적에 따라 고른다는 까닭을 썼는가"]},"explanation":["변화는 꺾은선그래프예요.","비율은 띠그래프·원그래프예요.","목적이 그래프를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#1','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','통계적 문제 해결의 첫 단계는 무엇인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."],"variant_rule":{"alt":[{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#2','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','통계적 탐구 문제로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":2,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 탄소 중립을 몇 개나 실천할까?","correct":true},{"t":"1 + 1은 얼마일까?","mis":"M6-1-u5-X13"},{"t":"3의 배수는 무엇일까?","mis":"M6-1-u5-X13"},{"t":"어제 날씨는 어땠을까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 반 친구들은 탄소 중립을 몇 개나 실천할까?」가 알맞아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 어떤 운동을 가장 좋아할까?","correct":true},{"t":"축구공은 무슨 모양일까?","mis":"M6-1-u5-X13"},{"t":"10을 2로 나누면 얼마일까?","mis":"M6-1-u5-X13"},{"t":"지금 몇 시일까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 반 친구들은 어떤 운동을 가장 좋아할까?」가 알맞아요."]},{"stem":"이번에는 다른 보기예요. 통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 학교 학생들은 주로 어떻게 학교에 올까?","correct":true},{"t":"학교는 몇 층일까?","mis":"M6-1-u5-X13"},{"t":"오늘은 무슨 요일일까?","mis":"M6-1-u5-X13"},{"t":"5 × 6은 얼마일까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 학교 학생들은 주로 어떻게 학교에 올까?」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#3','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"3개","correct":true},{"t":"1개 이하","mis":"M6-1-u5-X16"},{"t":"2개","mis":"M6-1-u5-X07"},{"t":"4개","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","3개가 37 %로 가장 커요.","그래서 답은 3개예요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"걷기","correct":true},{"t":"자동차","mis":"M6-1-u5-X16"},{"t":"버스","mis":"M6-1-u5-X07"},{"t":"자전거","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","걷기가 44 %로 가장 커요.","그래서 답은 걷기예요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"먹고 싶은 간식 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"떡볶이","correct":true},{"t":"과자","mis":"M6-1-u5-X16"},{"t":"과일","mis":"M6-1-u5-X07"},{"t":"빵","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","떡볶이가 35 %로 가장 커요.","그래서 답은 떡볶이예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#4','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'ox','auto','통계적 문제 해결은 자료 수집부터 시작해요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":1,"kind":"ox","stem":"통계적 문제 해결은 자료 수집부터 시작해요.","answer":"X","reason_options":[{"t":"무엇이 궁금한지 문제를 먼저 정해야 하기 때문에","correct":true},{"t":"자료가 있어야 문제를 정할 수 있기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"「1 + 1은 얼마일까?」는 통계적 탐구 문제로 알맞아요.","answer":"X","reason_options":[{"t":"자료를 모으지 않아도 답이 하나로 정해지기 때문에","correct":true},{"t":"수가 들어 있는 문제이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#5','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'sa','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C7","difficulty":2,"kind":"sa","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["4개는 18 %, 5개 이상은 14 %예요.","18 % + 14 % = 32 %예요.","답은 32예요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 2개와 3개를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["2개는 19 %, 3개는 37 %예요.","19 % + 37 % = 56 %예요.","답은 56이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 1개 이하와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["1개 이하는 12 %, 5개 이상은 14 %예요.","12 % + 14 % = 26 %예요.","답은 26이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#6','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제 제기 → 자료 수집 → 자료 분석 → 결과 해석","correct":true},{"t":"자료 수집 → 문제 제기 → 자료 분석 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"문제 제기 → 자료 분석 → 자료 수집 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"자료 수집 → 자료 분석 → 결과 해석 → 문제 제기","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기 → 자료 수집 → 자료 분석 → 결과 해석」이에요."]},{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#7','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 중립 실천 방법을 더 알리고 함께 실천해요","correct":true},{"t":"조사를 그만둬요","mis":"M6-1-u5-X13"},{"t":"그래프를 다시 그려요","mis":"M6-1-u5-X13"},{"t":"아무것도 하지 않아요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「탄소 중립 실천 방법을 더 알리고 함께 실천해요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"등굣길 안전 지도를 만들어 함께 살펴봐요","correct":true},{"t":"걸어서 오는 학생 수를 다시 세지 않아요","mis":"M6-1-u5-X13"},{"t":"그래프 색을 바꿔요","mis":"M6-1-u5-X13"},{"t":"결과를 숨겨요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「등굣길 안전 지도를 만들어 함께 살펴봐요」가 알맞아요."]},{"stem":"먹고 싶은 간식 조사에서 떡볶이가 35 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"학급 행사 간식으로 떡볶이를 먼저 생각해요","correct":true},{"t":"조사를 처음부터 다시 해요","mis":"M6-1-u5-X13"},{"t":"가장 적은 간식만 준비해요","mis":"M6-1-u5-X16"},{"t":"그래프를 버려요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「학급 행사 간식으로 떡볶이를 먼저 생각해요」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#8','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?',ARRAY['M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":8,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["18 + 14 = 32예요.","절반은 50 %예요.","32 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 2개와 3개를 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["19 + 37 = 56이에요.","절반은 50 %예요.","56 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"학교에 오는 방법 조사를 원그래프로 나타냈어요. 걷기는 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["걷기는 44 %예요.","절반은 50 %예요.","44 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#9','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'ox','auto','결과 해석에서 찾은 답을 실천 계획으로 이을 수 있어요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":9,"concept":"M6-1-u5-C7","difficulty":2,"kind":"ox","stem":"결과 해석에서 찾은 답을 실천 계획으로 이을 수 있어요.","answer":"O","reason_options":[{"t":"탐구한 답을 생활에서 쓰는 것이 마지막이기 때문에","correct":true},{"t":"해석한 뒤에는 할 일이 없기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"4개 18 %, 5개 이상 14 %이면 4개 이상은 32 %예요.","answer":"O","reason_options":[{"t":"18 + 14 = 32이기 때문에","correct":true},{"t":"18 × 14를 해야 하기 때문에","mis":"M6-1-u5-X15"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"그래프만 그리면 탐구 문제의 답을 저절로 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프를 읽고 해석해야 답을 얻기 때문에","correct":true},{"t":"그래프에 답이 적혀 있기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#10','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',3,'error','auto','「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X13','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C7","difficulty":3,"kind":"error","stem":"「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「먼저 그래프부터 그리고 나서 무엇을 조사할지 정하자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"도윤 — 「실천 개수를 손 들기로 모으자.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「모은 자료로 원그래프를 그려 분석하자.」","mis":"M6-1-u5-X16"}],"explanation":["탐구 문제를 정하는 것이 첫 단계예요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","하린은 단계를 바꾸거나 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자료를 모았으니 표나 그래프 없이 바로 결론을 내자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"예준 — 「좋아하는 운동을 붙임딱지로 모으자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「모은 자료로 띠그래프를 그려 보자.」","mis":"M6-1-u5-X16"}],"explanation":["모은 자료는 표·그래프로 분석한 뒤에 해석해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","수아는 단계를 바꾸거나 빠뜨렸어요."]},{"stem":"「우리 학교 학생들은 어떻게 학교에 올까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「그래프를 그렸으니 해석은 하지 않아도 돼.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"유진 — 「학교에 오는 방법을 조사해 표로 정리하자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「그래프를 보고 알게 된 것을 실천으로 이어 보자.」","mis":"M6-1-u5-X16"}],"explanation":["그래프를 그린 뒤에는 해석해서 답을 찾아야 해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","가온은 단계를 바꾸거나 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#1','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',2,'mc','auto','통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제 제기 → 자료 수집 → 자료 분석 → 결과 해석","correct":true},{"t":"자료 수집 → 문제 제기 → 자료 분석 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"문제 제기 → 자료 분석 → 자료 수집 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"자료 수집 → 자료 분석 → 결과 해석 → 문제 제기","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기 → 자료 수집 → 자료 분석 → 결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]},{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#2','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',2,'sa','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 조사한 전체는 25명이에요. 3개는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C7","difficulty":2,"kind":"sa","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 조사한 전체는 25명이에요. 3개는 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["3개는 36 %예요.","25 × 36 % = 9예요.","3개는 9명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 버스는 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["버스는 24 %예요.","50 × 24 % = 12예요.","버스는 12명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 과일은 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["과일은 30 %예요.","40 × 30 % = 12예요.","과일은 12명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#3','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'mc','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개와 4개를 합하면 전체의 절반보다 많은가요, 적은가요?',ARRAY['M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C7","difficulty":3,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개와 4개를 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["37 + 18 = 55예요.","절반은 50 %예요.","55 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 1개 이하, 2개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["12 + 19 + 14 = 45예요.","절반은 50 %예요.","45 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 떡볶이와 빵을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["35 + 20 = 55예요.","절반은 50 %예요.","55 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#4','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'mc','auto','우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":3,"kind":"mc","stem":"우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"등굣길 안전 지도를 만들어 함께 살펴봐요","correct":true},{"t":"걸어서 오는 학생 수를 다시 세지 않아요","mis":"M6-1-u5-X13"},{"t":"그래프 색을 바꿔요","mis":"M6-1-u5-X13"},{"t":"결과를 숨겨요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「등굣길 안전 지도를 만들어 함께 살펴봐요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사에서 떡볶이가 35 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"학급 행사 간식으로 떡볶이를 먼저 생각해요","correct":true},{"t":"조사를 처음부터 다시 해요","mis":"M6-1-u5-X13"},{"t":"가장 적은 간식만 준비해요","mis":"M6-1-u5-X16"},{"t":"그래프를 버려요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「학급 행사 간식으로 떡볶이를 먼저 생각해요」가 알맞아요."]},{"stem":"탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 중립 실천 방법을 더 알리고 함께 실천해요","correct":true},{"t":"조사를 그만둬요","mis":"M6-1-u5-X13"},{"t":"그래프를 다시 그려요","mis":"M6-1-u5-X13"},{"t":"아무것도 하지 않아요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「탄소 중립 실천 방법을 더 알리고 함께 실천해요」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#5','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'error','auto','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X13','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C7","difficulty":3,"kind":"error","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자료를 모았으니 표나 그래프 없이 바로 결론을 내자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"예준 — 「좋아하는 운동을 붙임딱지로 모으자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「모은 자료로 띠그래프를 그려 보자.」","mis":"M6-1-u5-X16"}],"explanation":["모은 자료는 표·그래프로 분석한 뒤에 해석해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","수아는 단계를 바꾸거나 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"「우리 학교 학생들은 어떻게 학교에 올까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「그래프를 그렸으니 해석은 하지 않아도 돼.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"유진 — 「학교에 오는 방법을 조사해 표로 정리하자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「그래프를 보고 알게 된 것을 실천으로 이어 보자.」","mis":"M6-1-u5-X16"}],"explanation":["그래프를 그린 뒤에는 해석해서 답을 찾아야 해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","가온은 단계를 바꾸거나 빠뜨렸어요."]},{"stem":"「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「먼저 그래프부터 그리고 나서 무엇을 조사할지 정하자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"시우 — 「실천 개수를 손 들기로 모으자.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「모은 자료로 원그래프를 그려 분석하자.」","mis":"M6-1-u5-X16"}],"explanation":["탐구 문제를 정하는 것이 첫 단계예요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","여울은 단계를 바꾸거나 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#6','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'ox','auto','통계적 문제 해결은 자료 수집부터 시작해요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C7","difficulty":3,"kind":"ox","stem":"통계적 문제 해결은 자료 수집부터 시작해요.","answer":"X","reason_options":[{"t":"무엇이 궁금한지 문제를 먼저 정해야 하기 때문에","correct":true},{"t":"자료가 있어야 문제를 정할 수 있기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"그래프만 그리면 탐구 문제의 답을 저절로 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프를 읽고 해석해야 답을 얻기 때문에","correct":true},{"t":"그래프에 답이 적혀 있기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"「1 + 1은 얼마일까?」는 통계적 탐구 문제로 알맞아요.","answer":"X","reason_options":[{"t":"자료를 모으지 않아도 답이 하나로 정해지기 때문에","correct":true},{"t":"수가 들어 있는 문제이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#7','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'sa','auto','탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈는데 2개의 백분율이 지워졌어요. 2개는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":3,"kind":"sa","stem":"탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈는데 2개의 백분율이 지워졌어요. 2개는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2개의 백분율은 100 − (12 + 36 + 20 + 12) = 20이에요.","25 × 20 % = 5예요.","2개는 5명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수","hide":[1]},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사(전체 50명)를 원그래프로 나타냈는데 자전거의 백분율이 지워졌어요. 자전거는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["자전거의 백분율은 100 − (44 + 24 + 12) = 20이에요.","50 × 20 % = 10이에요.","자전거는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법","hide":[2]}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 원그래프로 나타냈는데 빵의 백분율이 지워졌어요. 빵은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["빵의 백분율은 100 − (35 + 30 + 15) = 20이에요.","40 × 20 % = 8이에요.","빵은 8명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#8','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'sa','auto','탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C7","difficulty":4,"kind":"sa","stem":"탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["20 % + 12 % = 32 %예요.","25 × 32 % = 8이에요.","모두 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사(전체 50명)를 원그래프로 나타냈어요. 버스와 자동차를 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["24 % + 12 % = 36 %예요.","50 × 36 % = 18이에요.","모두 18명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈어요. 과학과 독서를 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["22 % + 14 % = 36 %예요.","50 × 36 % = 18이에요.","모두 18명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#9','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'sa','auto','3개를 실천한 학생은 9명이고, 이것은 전체의 36 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C7","difficulty":4,"kind":"sa","stem":"3개를 실천한 학생은 9명이고, 이것은 전체의 36 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["전체 × 36 % = 9예요.","1 %는 9 ÷ 36 = 0.25이고 전체 100 %는 그 100배예요.","0.25 × 100 = 25 — 전체는 25명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"버스로 오는 학생은 12명이고, 이것은 전체의 24 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["전체 × 24 % = 12예요.","1 %는 12 ÷ 24 = 0.5이고 전체 100 %는 그 100배예요.","0.5 × 100 = 50 — 전체는 50명이에요."]},{"stem":"떡볶이를 고른 학생은 14명이고, 이것은 전체의 35 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 35 % = 14예요.","1 %는 14 ÷ 35 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#10','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'essay','teacher','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C7","difficulty":4,"kind":"essay","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.","answer_guide":{"answer":"예: ① 문제 제기 — 탐구 문제를 정한다. ② 자료 수집 — 좋아하는 운동을 붙임딱지나 손 들기로 모은다. ③ 자료 분석 — 표로 정리해 백분율을 구하고 원그래프로 나타낸다. ④ 결과 해석 — 가장 많은 운동을 찾아 체육 시간이나 학급 행사 계획에 쓴다.","scoring_points":["네 단계를 차례대로 썼는가","자료 수집 방법을 구체적으로 썼는가","분석(표·그래프)과 해석(실천)을 구분했는가"]},"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석이에요.","분석은 표·그래프로 정리하는 일이에요.","해석한 결과를 실천으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#1','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'mc','auto','띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":1,"concept":"M6-1-u5-C8","difficulty":1,"kind":"mc","stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."],"variant_rule":{"alt":[{"stem":"비율그래프가 바르게 그려졌는지 확인하는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"색이 예쁜지 봐요","correct":true},{"t":"백분율의 합이 100인지 봐요","mis":"M6-1-u5-X16"},{"t":"칸의 길이가 백분율과 맞는지 봐요","mis":"M6-1-u5-X16"},{"t":"제목과 내용이 있는지 봐요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「색이 예쁜지 봐요」예요."]},{"stem":"잘못 그린 그래프를 그대로 쓰면 어떤 문제가 생기나요?","options":[{"t":"사실과 다르게 보여 틀린 판단을 하게 돼요","correct":true},{"t":"아무 문제도 없어요","mis":"M6-1-u5-X03"},{"t":"색이 모자라요","mis":"M6-1-u5-X16"},{"t":"종이가 아까워요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「사실과 다르게 보여 틀린 판단을 하게 돼요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#2','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#3','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'sa','auto','띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["모든 항목의 합은 100 %예요.","100 − 90 = 10이에요.","기타는 10 %여야 해요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["모든 항목의 합은 100 %예요.","100 − 90 = 10이에요.","기타는 10 %여야 해요."]},{"stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 85 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 합은 100 %예요.","100 − 85 = 15예요.","기타는 15 %여야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#4','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'ox','auto','비율그래프는 백분율의 합이 100 %인지 검토해야 해요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C8","difficulty":1,"kind":"ox","stem":"비율그래프는 백분율의 합이 100 %인지 검토해야 해요.","answer":"O","reason_options":[{"t":"전체가 100 %이기 때문에","correct":true},{"t":"합은 아무래도 상관없기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"칸의 길이가 백분율과 맞는지도 확인해야 해요.","answer":"O","reason_options":[{"t":"길이가 비율을 나타내기 때문에","correct":true},{"t":"길이는 아무렇게나 그려도 되기 때문에","mis":"M6-1-u5-X07"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"잘못 그린 그래프는 고쳐서 다시 그려야 해요.","answer":"O","reason_options":[{"t":"잘못된 그래프는 사실을 왜곡하기 때문에","correct":true},{"t":"한 번 그린 그래프는 고칠 수 없기 때문에","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#5','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','친구가 장래 희망 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16','M6-1-u5-X03']::text[],true,'{"seq":5,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"친구가 장래 희망 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 빌린 책의 종류 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["35 + 25 + 20 + 10 + 5 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["30 + 25 + 20 + 10 + 10 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#6','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#7','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','장래 희망 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":7,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"장래 희망 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"운동선수","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"의사","mis":"M6-1-u5-X07"},{"t":"예술가","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","운동선수가 30 %로 가장 커요.","그래서 답은 운동선수예요."],"asset":{"type":"pgr","kind":"band","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",10]],"title":"장래 희망"},"variant_rule":{"alt":[{"stem":"빌린 책의 종류 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"동화","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"과학","mis":"M6-1-u5-X07"},{"t":"역사","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","동화가 35 %로 가장 커요.","그래서 답은 동화예요."],"asset":{"type":"pgr","kind":"band","items":[["동화",35],["과학",25],["역사",20],["만화",15],["기타",5]],"title":"빌린 책의 종류"}},{"stem":"용돈 쓰임 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"저금","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"간식","mis":"M6-1-u5-X07"},{"t":"학용품","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","저금이 35 %로 가장 커요.","그래서 답은 저금이에요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#8','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','띠그래프에 운동선수 30 %, 의사 25 %라고 적혀 있는데 의사 칸이 운동선수 칸보다 길어요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X07']::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"띠그래프에 운동선수 30 %, 의사 25 %라고 적혀 있는데 의사 칸이 운동선수 칸보다 길어요. 무엇이 잘못되었나요?","options":[{"t":"칸의 길이가 백분율과 맞지 않아요","correct":true},{"t":"백분율의 합이 100이 아니에요","mis":"M6-1-u5-X03"},{"t":"의사 칸을 앞에 그려야 해요","mis":"M6-1-u5-X07"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X07"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「칸의 길이가 백분율과 맞지 않아요」예요."],"variant_rule":{"alt":[{"stem":"비율그래프가 바르게 그려졌는지 확인하는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"색이 예쁜지 봐요","correct":true},{"t":"백분율의 합이 100인지 봐요","mis":"M6-1-u5-X16"},{"t":"칸의 길이가 백분율과 맞는지 봐요","mis":"M6-1-u5-X16"},{"t":"제목과 내용이 있는지 봐요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「색이 예쁜지 봐요」예요."]},{"stem":"잘못 그린 그래프를 그대로 쓰면 어떤 문제가 생기나요?","options":[{"t":"사실과 다르게 보여 틀린 판단을 하게 돼요","correct":true},{"t":"아무 문제도 없어요","mis":"M6-1-u5-X03"},{"t":"색이 모자라요","mis":"M6-1-u5-X16"},{"t":"종이가 아까워요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「사실과 다르게 보여 틀린 판단을 하게 돼요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#9','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'ox','auto','백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":9,"concept":"M6-1-u5-C8","difficulty":2,"kind":"ox","stem":"백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.","answer":"X","reason_options":[{"t":"합이 100 %가 아니면 어떤 값이 잘못되었기 때문에","correct":true},{"t":"합이 100에 가까우면 괜찮기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.","answer":"X","reason_options":[{"t":"바른 그래프인지는 합과 길이로 확인하기 때문에","correct":true},{"t":"색이 예쁘면 값도 맞기 때문에","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"다른 항목의 합이 90 %이면 기타는 10 %예요.","answer":"O","reason_options":[{"t":"100 − 90 = 10이기 때문에","correct":true},{"t":"90 ÷ 9 = 10이기 때문에","mis":"M6-1-u5-X15"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#10','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',3,'error','auto','장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"도윤 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","하린은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"빌린 책의 종류 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"예준 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","수아는 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"소개하고 싶은 문화유산 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#1','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',2,'sa','auto','친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 45 %, 30 %, 20 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["45 + 30 + 20 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 33 %, 27 %, 19 %, 14 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["33 + 27 + 19 + 14 = 93이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 93이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#2','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',2,'sa','auto','띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["모든 항목의 합은 100 %예요.","100 − 88 = 12예요.","기타는 12 %여야 해요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 82 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["18"],"explanation":["모든 항목의 합은 100 %예요.","100 − 82 = 18이에요.","기타는 18 %여야 해요."]},{"stem":"이번에는 다른 보기예요. 띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["모든 항목의 합은 100 %예요.","100 − 88 = 12예요.","기타는 12 %여야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#3','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 의사 칸만 잘못 적혔어요. 의사의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 의사 칸만 잘못 적혔어요. 의사의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["의사를 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","의사는 25 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",15],["예술가",20],["선생님",15],["기타",10]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 마을 땅 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 밭 칸만 잘못 적혔어요. 밭의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["밭을 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","밭은 25 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"마을 땅 쓰임","items":[["논",40],["밭",15],["과수원",20],["기타",15]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#4','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'mc','auto','친구가 좋아하는 계절 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16','M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C8","difficulty":3,"kind":"mc","stem":"친구가 좋아하는 계절 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["32 + 28 + 24 + 6 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"좋아하는 계절","items":[["봄",32],["가을",28],["여름",24],["겨울",6]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 들고 싶은 동아리 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["36 + 28 + 12 + 14 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"들고 싶은 동아리","items":[["합창",36],["미술",28],["과학",12],["독서",14]],"bad":true}},{"stem":"친구가 마을 땅 쓰임 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["40 + 25 + 20 + 5 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"마을 땅 쓰임","items":[["논",40],["밭",25],["과수원",20],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#5','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'error','auto','좋아하는 계절 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"좋아하는 계절 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"예준 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","수아는 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"좋아하는 계절","items":[["봄",32],["가을",28],["여름",24],["겨울",6]],"bad":true},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"들고 싶은 동아리","items":[["합창",36],["미술",28],["과학",12],["독서",14]],"bad":true}},{"stem":"용돈 쓰임 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"시우 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","여울은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#6','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'ox','auto','그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":6,"concept":"M6-1-u5-C8","difficulty":3,"kind":"ox","stem":"그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.","answer":"X","reason_options":[{"t":"바른 그래프인지는 합과 길이로 확인하기 때문에","correct":true},{"t":"색이 예쁘면 값도 맞기 때문에","mis":"M6-1-u5-X16"}],"mis":"M6-1-u5-X16","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.","answer":"X","reason_options":[{"t":"합이 100 %가 아니면 어떤 값이 잘못되었기 때문에","correct":true},{"t":"합이 100에 가까우면 괜찮기 때문에","mis":"M6-1-u5-X03"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"비율그래프는 백분율의 합이 100 %인지 검토해야 해요.","answer":"O","reason_options":[{"t":"전체가 100 %이기 때문에","correct":true},{"t":"합은 아무래도 상관없기 때문에","mis":"M6-1-u5-X03"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#7','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'sa','auto','장래 희망 조사를 띠그래프로 나타냈어요. 운동선수의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"장래 희망 조사를 띠그래프로 나타냈어요. 운동선수의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["운동선수는 30 %, 기타는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 10 = 3 — 3배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",10]],"title":"장래 희망"},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 띠그래프로 나타냈어요. 저금의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["저금은 35 %, 기타는 5 %예요.","「몇 배」는 나눗셈으로 구해요.","35 ÷ 5 = 7 — 7배예요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈어요. 논의 비율은 과수원의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["논은 40 %, 과수원은 20 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 20 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#8','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 기타 칸만 잘못 적혔고 조사한 전체는 20명이에요. 기타는 실제로 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":4,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 기타 칸만 잘못 적혔고 조사한 전체는 20명이에요. 기타는 실제로 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["기타의 바른 백분율은 100 − 90 = 10이에요.","20 × 10 % = 2예요.","기타는 2명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 만화 칸만 잘못 적혔고 조사한 전체는 200권이에요. 만화는 실제로 몇 권인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["만화의 바른 백분율은 100 − 85 = 15예요.","200 × 15 % = 30이에요.","만화는 30권이에요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 종묘 칸만 잘못 적혔고 조사한 전체는 20명이에요. 종묘는 실제로 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["종묘의 바른 백분율은 100 − 85 = 15예요.","20 × 15 % = 3이에요.","종묘는 3명이에요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#9','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'sa','auto','친구가 그린 탄소 중립 실천 개수 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 3개 칸만 잘못 적혔어요. 3개의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C8","difficulty":4,"kind":"sa","stem":"친구가 그린 탄소 중립 실천 개수 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 3개 칸만 잘못 적혔어요. 3개의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["3개를 뺀 나머지의 합은 63 %예요.","100 − 63 = 37이에요.","3개는 37 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","title":"탄소 중립 실천 개수","items":[["1개 이하",12],["2개",19],["3개",27],["4개",18],["5개 이상",14]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 하루 폐기물 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 건설 칸만 잘못 적혔어요. 건설의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["건설을 뺀 나머지의 합은 62 %예요.","100 − 62 = 38이에요.","건설은 38 %로 고쳐요."],"asset":{"type":"pgr","kind":"pie","title":"하루 폐기물","items":[["사업장",49],["건설",28],["생활",13]],"bad":true}},{"stem":"친구가 그린 용돈 쓰임 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 간식 칸만 잘못 적혔어요. 간식의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["간식을 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","간식은 25 %로 고쳐요."],"asset":{"type":"pgr","kind":"pie","title":"용돈 쓰임","items":[["저금",35],["간식",15],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#10','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'essay','teacher','친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C8","difficulty":4,"kind":"essay","stem":"친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30 + 25 + 20 + 15 + 5 = 95이므로 합이 100 %가 아니다. 어떤 항목의 백분율이 잘못 적힌 것이다. 다시 세어 보니 기타가 틀렸다면 100 − 90 = 10이므로 기타는 10 %이다. 고친 백분율만큼 띠를 다시 나누어 그린다.","scoring_points":["합이 95라 잘못되었다고 찾았는가","기타를 10 %로 고쳤는가","고친 값만큼 다시 그린다고 썼는가"]},"explanation":["합이 95 %예요.","기타는 100 − 90 = 10 — 10 %예요.","고친 값만큼 다시 그려요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#1','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',1,'mc','auto','좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#2','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',1,'mc','auto','전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#3','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',1,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#4','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',1,'ox','auto','띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#5','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#6','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',1,'mc','auto','원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?',ARRAY['M6-1-u5-X06']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#7','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C7',1,'mc','auto','통계적 문제 해결의 첫 단계는 무엇인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]},{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#8','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#9','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#10','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#11','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',2,'sa','auto','전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]},{"stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#12','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#13','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#14','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#15','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',2,'mc','auto','띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."],"variant_rule":{"alt":[{"stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."]},{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#16','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#17','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#18','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#19','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#20','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',3,'mc','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#21','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',3,'error','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C3","difficulty":3,"kind":"error","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#22','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#23','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]},{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#24','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',4,'essay','teacher','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 「가 학교의 비율이 더 높으니 자전거를 타는 학생도 더 많다.」는 말이 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 「가 학교의 비율이 더 높으니 자전거를 타는 학생도 더 많다.」는 말이 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 학교는 200 × 25 % = 50이므로 50명, 나 학교는 300 × 20 % = 60이므로 60명이다. 비율은 가 학교가 높지만 전체 학생 수가 다르므로 자전거를 타는 학생 수는 나 학교가 더 많다.","scoring_points":["50명과 60명을 구했는가","나 학교가 더 많다고 답했는가","비율과 실제 수를 구분해 설명했는가"]},"explanation":["가 학교 50명, 나 학교 60명이에요.","나 학교가 더 많아요.","비율이 높아도 전체가 작으면 수는 적을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#25','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',4,'essay','teacher','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C1","difficulty":4,"kind":"essay","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 도시는 30 × 30 % = 9이므로 9일, 나 도시는 60 × 30 % = 18이므로 18일이다. 비율은 같아도 전체 날수가 다르므로 나쁨인 날수는 나 도시가 더 많다.","scoring_points":["9일과 18일을 구했는가","나 도시가 더 많다고 답했는가","전체가 다르면 같은 %라도 수가 다르다고 설명했는가"]},"explanation":["가 도시 9일, 나 도시 18일이에요.","나 도시가 더 많아요.","전체가 다르면 같은 %라도 수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#1','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',1,'mc','auto','미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#2','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',1,'mc','auto','6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X11']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]},{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#3','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',1,'sa','auto','좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."]},{"stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#4','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',1,'ox','auto','띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.',ARRAY['M6-1-u5-X07']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"mis":"M6-1-u5-X07","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#5','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#6','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',1,'mc','auto','원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?',ARRAY['M6-1-u5-X06','M6-1-u5-X16','M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#7','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C7',1,'mc','auto','모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."],"variant_rule":{"alt":[{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]},{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#8','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]},{"stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#9','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#10','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]},"variant_rule":{"alt":[{"stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#11','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',2,'sa','auto','전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]},{"stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#12','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#13','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]},{"stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#14','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#15','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',2,'mc','auto','「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]},{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#16','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#17','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',3,'sa','auto','미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#18','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#19','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#20','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',3,'mc','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#21','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C5',3,'error','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}},{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#22','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}},{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#23','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',4,'mc','auto','가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#24','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',4,'essay','teacher','외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C3","difficulty":4,"kind":"essay","stem":"외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 각 항목의 백분율을 구한다 — 경복궁 6 ÷ 20 × 100 = 30, 첨성대 25, 수원 화성 20, 종묘 15, 기타 10. ② 30 + 25 + 20 + 15 + 10 = 100이므로 합이 100 %인지 확인한다. ③ 백분율만큼 띠의 길이를 나눈다. ④ 나눈 칸에 내용과 백분율을 쓴다. ⑤ 제목을 쓴다.","scoring_points":["다섯 항목의 백분율을 바르게 구했는가","합이 100인지 확인했는가","띠 나누기 → 내용·백분율 → 제목 차례를 썼는가"]},"explanation":["백분율은 30, 25, 20, 15, 10 %예요.","30 + 25 + 20 + 15 + 10 = 100이에요.","띠 나누기 → 내용·백분율 → 제목 차례로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#25','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',4,'essay','teacher','「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 6개월 동안 읽은 책의 수 변화는 시간에 따른 변화이므로 꺾은선그래프가 알맞다. 이번 달 책의 종류별 비율은 전체에 대한 부분의 비율이므로 띠그래프나 원그래프가 알맞다. 보여 주고 싶은 것(목적)에 따라 그래프를 고른다.","scoring_points":["변화 → 꺾은선그래프를 골랐는가","비율 → 띠그래프·원그래프를 골랐는가","목적에 따라 고른다는 까닭을 썼는가"]},"explanation":["변화는 꺾은선그래프예요.","비율은 띠그래프·원그래프예요.","목적이 그래프를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#1','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',1,'mc','auto','소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#2','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C6',1,'mc','auto','학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#3','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',1,'sa','auto','기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."]},{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#4','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',1,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":1,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#5','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#6','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',1,'mc','auto','띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]},{"stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#7','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C7',1,'mc','auto','손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."],"variant_rule":{"alt":[{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]},{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#8','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#9','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#10','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#11','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',2,'sa','auto','전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."]},{"stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#12','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#13','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."]},{"stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#14','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#15','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',2,'mc','auto','「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]},{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#16','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',2,'mc','auto','반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X08','M6-1-u5-X03']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."]},{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#17','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',3,'sa','auto','소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#18','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#19','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#20','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',3,'mc','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#21','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',3,'error','auto','장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]},{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#22','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#23','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#24','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',4,'essay','teacher','눈금이 20칸인 원에 저금 35 %, 간식 25 %, 학용품 20 %, 선물 15 %, 기타 5 %를 원그래프로 나타내려고 해요. 저금과 간식은 각각 눈금 몇 칸인지 구하고, 선을 긋는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C4","difficulty":4,"kind":"essay","stem":"눈금이 20칸인 원에 저금 35 %, 간식 25 %, 학용품 20 %, 선물 15 %, 기타 5 %를 원그래프로 나타내려고 해요. 저금과 간식은 각각 눈금 몇 칸인지 구하고, 선을 긋는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 눈금 한 칸은 100 ÷ 20 = 5 (%)이다. 저금은 35 ÷ 5 = 7이므로 7칸, 간식은 25 ÷ 5 = 5이므로 5칸이다. 원의 중심에서 0 눈금, 7칸 눈금, 12칸 눈금까지 차례로 선을 그어 나누고 내용·백분율·제목을 쓴다.","scoring_points":["한 칸이 5 %임을 썼는가","7칸·5칸을 구했는가","원의 중심에서 선을 긋는다고 썼는가"]},"explanation":["한 칸은 5 %예요.","저금 7칸, 간식 5칸이에요.","원의 중심에서 눈금까지 선을 그어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#25','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C7',4,'essay','teacher','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C7","difficulty":4,"kind":"essay","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.","answer_guide":{"answer":"예: ① 문제 제기 — 탐구 문제를 정한다. ② 자료 수집 — 좋아하는 운동을 붙임딱지나 손 들기로 모은다. ③ 자료 분석 — 표로 정리해 백분율을 구하고 원그래프로 나타낸다. ④ 결과 해석 — 가장 많은 운동을 찾아 체육 시간이나 학급 행사 계획에 쓴다.","scoring_points":["네 단계를 차례대로 썼는가","자료 수집 방법을 구체적으로 썼는가","분석(표·그래프)과 해석(실천)을 구분했는가"]},"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석이에요.","분석은 표·그래프로 정리하는 일이에요.","해석한 결과를 실천으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#1','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',1,'mc','auto','해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#2','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',1,'mc','auto','하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]},{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#3','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C3',1,'sa','auto','해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."]},{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#4','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C7',1,'ox','auto','모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":1,"kind":"ox","stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#5','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#6','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C5',1,'mc','auto','모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12','M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."],"variant_rule":{"alt":[{"stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#7','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C7',1,'mc','auto','그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#8','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#9','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#10','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#11','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',2,'sa','auto','전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."]},{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#12','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#13','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#14','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#15','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',2,'mc','auto','올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."],"variant_rule":{"alt":[{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]},{"stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#16','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',2,'mc','auto','띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":16,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#17','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',3,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#18','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#19','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#20','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',3,'mc','auto','좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#21','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',3,'error','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C1","difficulty":3,"kind":"error","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#22','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#23','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]},{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#24','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C5',4,'essay','teacher','우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C5","difficulty":4,"kind":"essay","stem":"우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.","answer_guide":{"answer":"예: 가상 현실 16 ÷ 40 × 100 = 40, 로봇 30, 요리 20, 목공 10이고 합은 100 %이다. 이 백분율만큼 띠그래프(또는 원그래프)로 나타낸다. 그래프를 보면 가상 현실이 40 %로 가장 많고 목공의 4배이다.","scoring_points":["네 항목의 백분율을 구했는가","합 100을 확인하고 그래프로 나타낸다고 썼는가","그래프에서 바른 사실을 찾았는가"]},"explanation":["백분율은 40, 30, 20, 10 %예요.","합이 100 %인지 확인하고 그래프로 나타내요.","가상 현실이 가장 많고 목공의 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#25','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',4,'essay','teacher','친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C8","difficulty":4,"kind":"essay","stem":"친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30 + 25 + 20 + 15 + 5 = 95이므로 합이 100 %가 아니다. 어떤 항목의 백분율이 잘못 적힌 것이다. 다시 세어 보니 기타가 틀렸다면 100 − 90 = 10이므로 기타는 10 %이다. 고친 백분율만큼 띠를 다시 나누어 그린다.","scoring_points":["합이 95라 잘못되었다고 찾았는가","기타를 10 %로 고쳤는가","고친 값만큼 다시 그린다고 썼는가"]},"explanation":["합이 95 %예요.","기타는 100 − 90 = 10 — 10 %예요.","고친 값만큼 다시 그려요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
